  </style>
<div id="ord-frac-app" style="margin: 15px auto; max-width: 820px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; user-select: none;"></div>
<p>
<script>
(function() {
  let fracciones = [];
  let estadoSlots = [null, null, null, null];
  let fichaSeleccionada = null;
  let arrastrando = null;

  window.generarNuevoRetoFracciones = function() {
    estadoSlots = [null, null, null, null];
    fichaSeleccionada = null;
    arrastrando = null;

    let fb = document.getElementById('feedback-orden');
    if (fb) fb.innerHTML = '';

    let pool = [
      { num: 1, den: 4 }, { num: 1, den: 3 }, { num: 1, den: 2 },
      { num: 2, den: 5 }, { num: 3, den: 5 }, { num: 4, den: 5 },
      { num: 2, den: 3 }, { num: 3, den: 4 }, { num: 4, den: 7 },
      { num: 5, den: 6 }, { num: 5, den: 4 }, { num: 7, den: 5 },
      { num: 3, den: 2 }, { num: 7, den: 3 }, { num: 8, den: 2 },
      { num: 9, den: 1 }, { num: 5, den: 2 }, { num: 7, den: 2 }
    ];

    let seleccionadas = [];
    pool.sort(function() { return Math.random() - 0.5; });

    for (let i = 0; i < pool.length; i++) {
      let f = pool[i];
      let val = f.num / f.den;
      let repetido = false;
      for (let j = 0; j < seleccionadas.length; j++) {
        if (Math.abs(seleccionadas[j].val - val) < 0.001) {
          repetido = true;
          break;
        }
      }
      if (!repetido) {
        seleccionadas.push({ num: f.num, den: f.den, val: val });
        if (seleccionadas.length === 4) break;
      }
    }

    fracciones = [];
    for (let k = 0; k < seleccionadas.length; k++) {
      fracciones.push({
        id: 'frac-' + k,
        num: seleccionadas[k].num,
        den: seleccionadas[k].den,
        val: seleccionadas[k].val
      });
    }

    renderizarTablero();
  };

  function renderizarTablero() {
    const banco = document.getElementById('ord-banco-fracciones');
    if (!banco) return;
    banco.innerHTML = '';

    const slots = document.querySelectorAll('.ord-hueco');
    slots.forEach(function(s, idx) {
      s.innerHTML = '';
      s.style.borderColor = '#f59e0b';
      s.style.background = '#fde09c';
      s.onclick = function() { clicEnSlot(idx); };
    });

    fracciones.forEach(function(f) {
      let fichaEl = crearFichaDOM(f);
      let slotIdx = estadoSlots.indexOf(f.id);

      if (slotIdx !== -1) {
        if (slots[slotIdx]) slots[slotIdx].appendChild(fichaEl);
      } else {
        banco.appendChild(fichaEl);
      }
    });
  }

  function crearFichaDOM(f) {
    let div = document.createElement('div');
    div.className = 'ord-ficha';
    div.id = f.id;

    div.innerHTML = '<span class="ord-num">' + f.num + '</span>' +
                    '<div class="ord-barra"></div>' +
                    '<span class="ord-den">' + f.den + '</span>';

    div.onclick = function(e) {
      e.stopPropagation();
      clicEnFicha(f.id);
    };

    div.draggable = true;
    div.ondragstart = function(e) {
      arrastrando = f.id;
      if (e.dataTransfer) {
        e.dataTransfer.setData('text/plain', f.id);
      }
    };

    div.ontouchstart = function() {
      arrastrando = f.id;
    };

    div.ontouchend = function(e) {
      if (!arrastrando) return;
      let touch = e.changedTouches[0];
      let elemDebajo = document.elementFromPoint(touch.clientX, touch.clientY);
      let slotCercano = elemDebajo ? elemDebajo.closest('.ord-hueco') : null;
      let bancoCercano = elemDebajo ? elemDebajo.closest('#ord-banco-fracciones') : null;

      if (slotCercano) {
        let idx = parseInt(slotCercano.getAttribute('data-slot'));
        asignarFichaASlot(arrastrando, idx);
      } else if (bancoCercano) {
        devolverFichaAlBanco(arrastrando);
      }
      arrastrando = null;
    };

    return div;
  }

  document.querySelectorAll('.ord-hueco').forEach(function(slot) {
    slot.ondragover = function(e) { e.preventDefault(); };
    slot.ondrop = function(e) {
      e.preventDefault();
      let id = (e.dataTransfer ? e.dataTransfer.getData('text/plain') : null) || arrastrando;
      let slotIdx = parseInt(slot.getAttribute('data-slot'));
      if (id) asignarFichaASlot(id, slotIdx);
    };
  });

  const banco = document.getElementById('ord-banco-fracciones');
  if (banco) {
    banco.ondragover = function(e) { e.preventDefault(); };
    banco.ondrop = function(e) {
      e.preventDefault();
      let id = (e.dataTransfer ? e.dataTransfer.getData('text/plain') : null) || arrastrando;
      if (id) devolverFichaAlBanco(id);
    };
    banco.onclick = function() {
      if (fichaSeleccionada) {
        devolverFichaAlBanco(fichaSeleccionada);
        deseleccionarTodo();
      }
    };
  }

  function clicEnFicha(id) {
    if (fichaSeleccionada === id) {
      let slotIdx = estadoSlots.indexOf(id);
      if (slotIdx !== -1) {
        devolverFichaAlBanco(id);
      }
      deseleccionarTodo();
    } else {
      deseleccionarTodo();
      fichaSeleccionada = id;
      let el = document.getElementById(id);
      if (el) el.classList.add('seleccionada');
    }
  }

  function clicEnSlot(slotIdx) {
    if (fichaSeleccionada) {
      asignarFichaASlot(fichaSeleccionada, slotIdx);
      deseleccionarTodo();
    } else {
      let fichaEnSlot = estadoSlots[slotIdx];
      if (fichaEnSlot) {
        devolverFichaAlBanco(fichaEnSlot);
      }
    }
  }

  function deseleccionarTodo() {
    fichaSeleccionada = null;
    document.querySelectorAll('.ord-ficha').forEach(function(el) {
      el.classList.remove('seleccionada');
    });
  }

  function asignarFichaASlot(idFicha, targetSlot) {
    let slotPrevio = estadoSlots.indexOf(idFicha);
    if (slotPrevio !== -1) estadoSlots[slotPrevio] = null;

    let fichaExistente = estadoSlots[targetSlot];
    if (fichaExistente && fichaExistente !== idFicha) {
      if (slotPrevio !== -1) {
        estadoSlots[slotPrevio] = fichaExistente;
      }
    }

    estadoSlots[targetSlot] = idFicha;
    renderizarTablero();
  }

  function devolverFichaAlBanco(idFicha) {
    let slotIdx = estadoSlots.indexOf(idFicha);
    if (slotIdx !== -1) {
      estadoSlots[slotIdx] = null;
      renderizarTablero();
    }
  }

  window.comprobarOrdenFracciones = function() {
    const fb = document.getElementById('feedback-orden');
    let slots = document.querySelectorAll('.ord-hueco');

    if (estadoSlots.indexOf(null) !== -1) {
      fb.style.color = '#dc2626';
      fb.innerHTML = 'Coloca las 4 fracciones en los huecos antes de comprobar.';
      return;
    }

    let valoresColocados = estadoSlots.map(function(id) {
      for (let i = 0; i < fracciones.length; i++) {
        if (fracciones[i].id === id) return fracciones[i].val;
      }
      return 0;
    });

    let esCreciente = true;
    for (let i = 0; i < valoresColocados.length - 1; i++) {
      if (valoresColocados[i] >= valoresColocados[i + 1]) {
        esCreciente = false;
        break;
      }
    }

    if (esCreciente) {
      fb.style.color = '#15803d';
      fb.innerHTML = '🎉 ¡Perfecto! Las fracciones están ordenadas de menor a mayor correctamente.';
      slots.forEach(function(s) {
        s.style.borderColor = '#16a34a';
        s.style.background = '#dcfce7';
      });
    } else {
      fb.style.color = '#b91c1c';
      fb.innerHTML = 'El orden no es correcto. Compara las fracciones pasando a decimal o reduciendo a común denominador.';
      slots.forEach(function(s) {
        s.style.borderColor = '#dc2626';
        s.style.background = '#fee2e2';
      });
    }
  };

  // Inicialización directa e inmediata
  window.generarNuevoRetoFracciones();
})();
</script>
