<div id="tutor-frac-app" style="margin: 10px 0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b;"></div>
<script>
(function() {
  let tipoActual = 1;
  let pasoIndex = 0;
  let pasos = [];
  let casoData = null;
  let ultimoNumAcertado = 0;
  let ultimoDenAcertado = 0;

  function mcd(a, b) {
    a = Math.abs(a); b = Math.abs(b);
    while (b) { let t = b; b = a % b; a = t; }
    return a;
  }
  function mcm(a, b) {
    return Math.abs(a * b) / mcd(a, b);
  }
  function randInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function htmlFrac(n, d) {
    if (d === 1) return '<span>' + n + '</span>';
    return '<span class="frac-box">' +
             '<span class="f-num">' + n + '</span>' +
             '<span class="f-line"></span>' +
             '<span class="f-den">' + d + '</span>' +
           '</span>';
  }

  window.cambiarTipo = function(t) {
    tipoActual = t;
    document.getElementById('btn-tipo-1').style.background = (t === 1) ? '#0284c7' : '#e2e8f0';
    document.getElementById('btn-tipo-1').style.color = (t === 1) ? 'white' : '#334155';
    document.getElementById('btn-tipo-2').style.background = (t === 2) ? '#0284c7' : '#e2e8f0';
    document.getElementById('btn-tipo-2').style.color = (t === 2) ? 'white' : '#334155';
    nuevoEjercicioFrac();
  };

  const PAREJAS_DENOMINADORES = [
    [2, 4], [2, 6], [3, 6], [4, 2], [6, 3], [3, 4], [2, 3], [5, 2]
  ];

  function generarCasoTipo1() {
    let p1, p2, resNum1, resDen1, resNum2, resDen2;

    do {
      let pDens1 = PAREJAS_DENOMINADORES[randInt(0, PAREJAS_DENOMINADORES.length - 1)];
      let d1 = pDens1[0], d2 = pDens1[1];
      let n1 = randInt(1, 4), n2 = randInt(1, 3);
      let op = Math.random() > 0.5 ? '+' : '-';
      let com = mcm(d1, d2);
      let t1 = n1 * (com / d1);
      let t2 = n2 * (com / d2);
      resNum1 = (op === '+') ? t1 + t2 : t1 - t2;
      resDen1 = com;
      p1 = { n1, d1, n2, d2, op, com, t1, t2 };
    } while (resNum1 === 0);

    do {
      let pDens2 = PAREJAS_DENOMINADORES[randInt(0, PAREJAS_DENOMINADORES.length - 1)];
      let d1 = pDens2[0], d2 = pDens2[1];
      let n1 = randInt(1, 4), n2 = randInt(1, 3);
      let op = Math.random() > 0.5 ? '+' : '-';
      let com = mcm(d1, d2);
      let t1 = n1 * (com / d1);
      let t2 = n2 * (com / d2);
      resNum2 = (op === '+') ? t1 + t2 : t1 - t2;
      resDen2 = com;
      p2 = { n1, d1, n2, d2, op, com, t1, t2 };
    } while (resNum2 === 0);

    let prodNum = resNum1 * resNum2;
    let prodDen = resDen1 * resDen2;
    let dCom = mcd(prodNum, prodDen);
    let simpNum = prodNum / dCom;
    let simpDen = prodDen / dCom;
    if (simpDen < 0) { simpNum = -simpNum; simpDen = -simpDen; }

    let p1HTML = '(' + htmlFrac(p1.n1, p1.d1) + ' ' + p1.op + ' ' + htmlFrac(p1.n2, p1.d2) + ')';
    let p2HTML = '(' + htmlFrac(p2.n1, p2.d1) + ' ' + p2.op + ' ' + htmlFrac(p2.n2, p2.d2) + ')';
    let exprTotalHTML = p1HTML + ' &nbsp;·&nbsp; ' + p2HTML;

    let listaPasos = [
      {
        titulo: 'Paso 1: Resolver el primer paréntesis',
        instruccion: 'Calcula el común denominador y opera el interior del primer paréntesis:',
        subHTML: p1HTML,
        expNum: resNum1, expDen: resDen1,
        pista: 'm.c.m.(' + p1.d1 + ', ' + p1.d2 + ') = ' + p1.com + '. Fracciones equivalentes: ' + p1.t1 + '/' + p1.com + ' y ' + p1.t2 + '/' + p1.com + '.'
      },
      {
        titulo: 'Paso 2: Resolver el segundo paréntesis',
        instruccion: 'Calcula el común denominador y opera el segundo paréntesis:',
        subHTML: p2HTML,
        expNum: resNum2, expDen: resDen2,
        pista: 'm.c.m.(' + p2.d1 + ', ' + p2.d2 + ') = ' + p2.com + '. Fracciones equivalentes: ' + p2.t1 + '/' + p2.com + ' y ' + p2.t2 + '/' + p2.com + '.'
      },
      {
        titulo: 'Paso 3: Multiplicar los resultados',
        instruccion: 'Multiplica en línea (numerador por numerador y denominador por denominador):',
        subHTML: htmlFrac(resNum1, resDen1) + ' &nbsp;·&nbsp; ' + htmlFrac(resNum2, resDen2),
        expNum: prodNum, expDen: prodDen,
        pista: 'Multiplica: (' + resNum1 + ' · ' + resNum2 + ') arriba y (' + resDen1 + ' · ' + resDen2 + ') abajo.'
      }
    ];

    if (dCom > 1) {
      listaPasos.push({
        titulo: 'Paso 4: Simplificar la fracción final',
        instruccion: 'Divide numerador y denominador entre su Máximo Común Divisor (' + dCom + '):',
        subHTML: 'Simplificar ' + htmlFrac(prodNum, prodDen),
        expNum: simpNum, expDen: simpDen,
        pista: 'Tanto ' + prodNum + ' como ' + prodDen + ' se pueden dividir entre ' + dCom + '.'
      });
    }

    return { exprHTML: exprTotalHTML, pasos: listaPasos, finalNum: simpNum, finalDen: simpDen };
  }

  function generarCasoTipo2() {
    let p1, p2, resNum1, resDen1, resNum2, resDen2;

    do {
      let ent1 = randInt(-2, 2); if (ent1 === 0) ent1 = 1;
      let pDens1 = PAREJAS_DENOMINADORES[randInt(0, PAREJAS_DENOMINADORES.length - 1)];
      let d1 = pDens1[0], d2 = pDens1[1];
      let n1 = randInt(1, 3), n2 = randInt(1, 2);
      let op1 = Math.random() > 0.4 ? '+' : '-';
      let op2 = Math.random() > 0.5 ? '-' : '+';

      let com = mcm(d1, d2);
      let termEnt = ent1 * com;
      let term1 = (op1 === '+') ? n1 * (com / d1) : -n1 * (com / d1);
      let term2 = (op2 === '+') ? n2 * (com / d2) : -n2 * (com / d2);

      resNum1 = termEnt + term1 + term2;
      resDen1 = com;
      p1 = { ent: ent1, n1, d1, op1, n2, d2, op2, com, termEnt, term1, term2 };
    } while (resNum1 === 0);

    do {
      let ent2 = randInt(1, 3);
      let d = [2, 3, 4, 5][randInt(0, 3)];
      let n = randInt(1, 3);
      let op = Math.random() > 0.5 ? '-' : '+';
      let termEnt = ent2 * d;
      let termFrac = (op === '+') ? n : -n;
      resNum2 = termEnt + termFrac;
      resDen2 = d;
      p2 = { ent: ent2, n, d, op, termEnt, termFrac };
    } while (resNum2 === 0);

    let divNum = resNum1 * resDen2;
    let divDen = resDen1 * resNum2;
    if (divDen < 0) { divNum = -divNum; divDen = -divDen; }

    let dCom = mcd(divNum, divDen);
    let simpNum = divNum / dCom;
    let simpDen = divDen / dCom;

    let p1HTML = '(' + p1.ent + ' ' + p1.op1 + ' ' + htmlFrac(p1.n1, p1.d1) + ' ' + p1.op2 + ' ' + htmlFrac(p1.n2, p1.d2) + ')';
    let p2HTML = '(' + p2.ent + ' ' + p2.op + ' ' + htmlFrac(p2.n, p2.d) + ')';
    let exprTotalHTML = p1HTML + ' &nbsp;:&nbsp; ' + p2HTML;

    let listaPasos = [
      {
        titulo: 'Paso 1: Resolver el primer paréntesis',
        instruccion: 'Recuerda que el entero tiene denominador 1. Halla el m.c.m. y opera:',
        subHTML: p1HTML,
        expNum: resNum1, expDen: resDen1,
        pista: 'Pon ' + p1.ent + ' como ' + p1.ent + '/1. El m.c.m.(1, ' + p1.d1 + ', ' + p1.d2 + ') es ' + p1.com + '. Numeradores: ' + p1.termEnt + ' + (' + p1.term1 + ') + (' + p1.term2 + ').'
      },
      {
        titulo: 'Paso 2: Resolver el segundo paréntesis',
        instruccion: 'Reduce a común denominador y calcula el segundo paréntesis:',
        subHTML: p2HTML,
        expNum: resNum2, expDen: resDen2,
        pista: 'El entero ' + p2.ent + ' equivale a ' + p2.termEnt + '/' + p2.d + '. Al sumarle/restarle ' + p2.n + '/' + p2.d + ' queda ' + resNum2 + '/' + resDen2 + '.'
      },
      {
        titulo: 'Paso 3: Realizar la división',
        instruccion: 'Divide multiplicando en cruz:',
        subHTML: htmlFrac(resNum1, resDen1) + ' &nbsp;:&nbsp; ' + htmlFrac(resNum2, resDen2),
        expNum: divNum, expDen: divDen,
        pista: 'Multiplica en cruz: (' + resNum1 + ' · ' + resDen2 + ') arriba y (' + resDen1 + ' · ' + resNum2 + ') abajo.'
      }
    ];

    if (dCom > 1) {
      listaPasos.push({
        titulo: 'Paso 4: Simplificar la fracción final',
        instruccion: 'Divide numerador y denominador entre su factor común (' + dCom + '):',
        subHTML: 'Simplificar ' + htmlFrac(divNum, divDen),
        expNum: simpNum, expDen: simpDen,
        pista: 'Tanto ' + divNum + ' como ' + divDen + ' se pueden dividir entre ' + dCom + '.'
      });
    }

    return { exprHTML: exprTotalHTML, pasos: listaPasos, finalNum: simpNum, finalDen: simpDen };
  }

  window.nuevoEjercicioFrac = function() {
    pasoIndex = 0;
    document.getElementById('historial-pasos-frac').style.display = 'none';
    document.getElementById('lista-historial-frac').innerHTML = '';
    document.getElementById('tarjeta-paso-activo').style.display = 'block';
    document.getElementById('tarjeta-final-frac').style.display = 'none';

    casoData = (tipoActual === 1) ? generarCasoTipo1() : generarCasoTipo2();
    pasos = casoData.pasos;

    document.getElementById('disp-expr-original').innerHTML = casoData.exprHTML;
    cargarPasoFrac();
  };

  function cargarPasoFrac() {
    let p = pasos[pasoIndex];
    document.getElementById('txt-subtitulo-paso').textContent = p.titulo;
    document.getElementById('txt-instruccion-frac').textContent = p.instruccion;
    document.getElementById('disp-sub-operacion').innerHTML = p.subHTML;

    let inpNum = document.getElementById('inp-num-frac');
    let inpDen = document.getElementById('inp-den-frac');
    inpNum.value = '';
    inpDen.value = '';
    inpNum.disabled = false;
    inpDen.disabled = false;
    inpNum.focus();

    document.getElementById('btn-comprobar-paso').style.display = 'inline-block';
    document.getElementById('contenedor-btn-siguiente').style.display = 'none';
    document.getElementById('fb-paso-frac').innerHTML = '';
    document.getElementById('panel-pista-frac').style.display = 'none';
    document.getElementById('panel-pista-frac').textContent = p.pista;
  }

  window.togglePistaFrac = function() {
    let p = document.getElementById('panel-pista-frac');
    p.style.display = (p.style.display === 'none') ? 'block' : 'none';
  };

  window.validarPasoFrac = function() {
    let p = pasos[pasoIndex];
    let num = parseInt(document.getElementById('inp-num-frac').value.trim());
    let den = parseInt(document.getElementById('inp-den-frac').value.trim());
    let fb = document.getElementById('fb-paso-frac');

    if (isNaN(num) || isNaN(den)) {
      fb.style.color = '#dc2626';
      fb.innerHTML = 'Introduce números enteros válidos en numerador y denominador.';
      return;
    }
    if (den === 0) {
      fb.style.color = '#dc2626';
      fb.innerHTML = 'El denominador no puede ser 0.';
      return;
    }

    if (den < 0) { num = -num; den = -den; }

    let esExacto = (num === p.expNum && den === p.expDen);
    let esEquivalente = (num * p.expDen === den * p.expNum);

    if (esExacto || (esEquivalente && pasoIndex < pasos.length - 1)) {
      ultimoNumAcertado = num;
      ultimoDenAcertado = den;

      fb.style.color = '#16a34a';
      fb.innerHTML = '✓ ¡Paso correcto! Revisa el resultado y pulsa en continuar cuando estés listo.';

      // Bloquear inputs para que no los altere
      document.getElementById('inp-num-frac').disabled = true;
      document.getElementById('inp-den-frac').disabled = true;
      document.getElementById('btn-comprobar-paso').style.display = 'none';

      // Mostrar botón manual de siguiente paso
      let btnSig = document.getElementById('btn-siguiente-paso');
      let esUltimo = (pasoIndex === pasos.length - 1);
      btnSig.innerHTML = esUltimo ? 'Ver resultado final &rarr;' : 'Siguiente paso &rarr;';
      document.getElementById('contenedor-btn-siguiente').style.display = 'block';
    } else {
      fb.style.color = '#dc2626';
      fb.innerHTML = '✗ Revisa los cálculos. Pulsa en la pista si necesitas ayuda con el común denominador.';
    }
  };

  window.avanzarSiguientePaso = function() {
    let p = pasos[pasoIndex];

    // Registrar en el historial de pasos
    document.getElementById('historial-pasos-frac').style.display = 'block';
    let hist = document.getElementById('lista-historial-frac');
    let item = document.createElement('div');
    item.style.background = '#ffffff';
    item.style.border = '1px solid #e2e8f0';
    item.style.borderRadius = '8px';
    item.style.padding = '8px 14px';
    item.style.display = 'flex';
    item.style.justifyContent = 'space-between';
    item.style.alignItems = 'center';
    item.style.flexWrap = 'wrap';
    item.style.gap = '6px';
    item.innerHTML = '<span style="color: #475569; font-weight:600;">' + p.titulo + ':</span>' +
                     '<span style="font-weight: 800; color: #16a34a; display: flex; align-items:center; gap:6px;">' +
                       p.subHTML + ' = ' + htmlFrac(ultimoNumAcertado, ultimoDenAcertado) +
                     '</span>';
    hist.appendChild(item);

    pasoIndex++;

    if (pasoIndex < pasos.length) {
      cargarPasoFrac();
    } else {
      document.getElementById('tarjeta-paso-activo').style.display = 'none';
      document.getElementById('tarjeta-final-frac').style.display = 'block';
      document.getElementById('txt-resultado-final-frac').innerHTML =
        '<span>Resultado final irreducible:</span> ' + htmlFrac(casoData.finalNum, casoData.finalDen);
    }
  };

  // Permitir comprobar pulsando Enter en los inputs
  ['inp-num-frac', 'inp-den-frac'].forEach(function(id) {
    let el = document.getElementById(id);
    if (el) {
      el.addEventListener('keypress', function(e) {
        if (e.key === 'Enter') {
          let btnComp = document.getElementById('btn-comprobar-paso');
          if (btnComp && btnComp.style.display !== 'none') {
            validarPasoFrac();
          } else {
            let btnSig = document.getElementById('contenedor-btn-siguiente');
            if (btnSig && btnSig.style.display !== 'none') {
              avanzarSiguientePaso();
            }
          }
        }
      });
    }
  });

  window.nuevoEjercicioFrac();
})();
</script>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

