<div id="frac-tutor-colorear" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera sin contenedor externo -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">Representación de Fracciones</h3>
<button id="btn-nueva-frac" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 20px;">Colorea la parte que representa la siguiente fracción haciendo clic en las porciones:</p>
<div style="display: flex; justify-content: center; align-items: center; gap: 40px; flex-wrap: wrap;"><!-- Fracción tipográfica -->
<div id="disp-fraccion" style="background: #f8fafc; padding: 20px 30px; border-radius: 12px; border: 2px solid #cbd5e1; box-shadow: 0 4px 6px rgba(0,0,0,0.05);"><!-- Se inyecta por JS --></div>
<!-- Gráfico interactivo SVG -->
<div id="svg-container" style="display: flex; justify-content: center; align-items: center;"><!-- Se inyecta por JS --></div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-frac" class="frac-btn frac-btn-check">Comprobar Resultado</button>
<div id="fb-mensaje" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 28px;"></div>
</div>
</div>
<p>
<script>
(function() {
  let numeradorObjetivo = 0;
  let denominadorObjetivo = 0;
  let porcionesColoreadas = 0;

  function renderFraccion(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function generarGraficoSVG(den) {
    let svg = '<svg width="220" height="220" viewBox="-110 -110 220 220" style="transform: rotate(-90deg); overflow: visible; drop-shadow: 0 4px 6px rgba(0,0,0,0.1);">';

    if (den === 1) {
      svg += `<circle cx="0" cy="0" r="100" fill="#f8fafc" stroke="#334155" stroke-width="3" class="slice" data-selected="false" style="cursor:pointer; transition: fill 0.2s;"></circle>`;
    } else {
      let angulo = (2 * Math.PI) / den;
      for (let i = 0; i < den; i++) {
        let a1 = i * angulo;
        let a2 = (i + 1) * angulo;
        let x1 = 100 * Math.cos(a1);
        let y1 = 100 * Math.sin(a1);
        let x2 = 100 * Math.cos(a2);
        let y2 = 100 * Math.sin(a2);

        let largeArc = (a2 - a1) > Math.PI ? 1 : 0;
        let pathData = `M 0 0 L ${x1} ${y1} A 100 100 0 ${largeArc} 1 ${x2} ${y2} Z`;

        svg += `<path d="${pathData}" fill="#f8fafc" stroke="#334155" stroke-width="3" class="slice" data-selected="false" style="cursor:pointer; transition: fill 0.2s;"></path>`;
      }
    }
    svg += '</svg>';
    return svg;
  }

  function generarNuevoEjercicio() {
    denominadorObjetivo = Math.floor(Math.random() * 9) + 2;
    numeradorObjetivo = Math.floor(Math.random() * denominadorObjetivo) + 1;
    porcionesColoreadas = 0;

    document.getElementById('disp-fraccion').innerHTML = renderFraccion(numeradorObjetivo, denominadorObjetivo);
    document.getElementById('svg-container').innerHTML = generarGraficoSVG(denominadorObjetivo);

    let fb = document.getElementById('fb-mensaje');
    fb.innerHTML = '';
    fb.style.color = '';

    document.getElementById('btn-comprobar-frac').disabled = false;
    document.getElementById('btn-comprobar-frac').style.opacity = '1';
  }

  function interactuarPorcion(e) {
    let target = e.target;
    if (target && target.getAttribute('data-selected') !== null) {
      let isSelected = target.getAttribute('data-selected') === 'true';

      if (!isSelected) {
        target.setAttribute('fill', '#0ea5e9'); 
        target.setAttribute('data-selected', 'true');
        porcionesColoreadas++;
      } else {
        target.setAttribute('fill', '#f8fafc'); 
        target.setAttribute('data-selected', 'false');
        porcionesColoreadas--;
      }
    }
  }

  function comprobarResultado() {
    let fb = document.getElementById('fb-mensaje');
    if (porcionesColoreadas === numeradorObjetivo) {
      fb.style.color = '#10b981';
      fb.innerHTML = '✓ ¡Correcto! Has coloreado exactamente la fracción indicada.';
      document.getElementById('btn-comprobar-frac').disabled = true;
      document.getElementById('btn-comprobar-frac').style.opacity = '0.5';
    } else {
      fb.style.color = '#ef4444';
      let exceso = porcionesColoreadas > numeradorObjetivo;
      fb.innerHTML = `✗ Incorrecto. Has coloreado ${porcionesColoreadas} porcion${porcionesColoreadas === 1 ? 'es' : 'es'}. ${exceso ? 'Te has pasado.' : 'Te faltan porciones.'}`;
    }
  }

  function inicializarEventos() {
    document.getElementById('btn-nueva-frac').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-frac').addEventListener('click', comprobarResultado);
    document.getElementById('svg-container').addEventListener('click', interactuarPorcion);
    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

