<div id="frac-tutor-impropias" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;">
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">Fracciones Impropias</h3>
<button id="btn-nueva-impropia" class="frac-btn">Nuevo Ejercicio</button></div>
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 20px;">Colorea las porciones necesarias para representar la siguiente fracción:</p>
<div style="display: flex; justify-content: center; align-items: center; gap: 30px; flex-wrap: wrap;">
<div id="disp-fraccion-impropia" style="background: #f8fafc; padding: 15px 30px; border-radius: 12px; border: 2px solid #cbd5e1; box-shadow: 0 4px 6px rgba(0,0,0,0.05);"><!-- Se inyecta por JS --></div>
<div id="svg-container-impropia" style="display: flex; justify-content: center; align-items: center; flex-wrap: wrap; max-width: 600px; gap: 10px;"><!-- Se inyecta por JS --></div>
</div>
</div>
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-impropia" class="frac-btn frac-btn-check">Comprobar Resultado</button>
<div id="fb-mensaje-impropia" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 28px;"></div>
</div>
</div>
<p>
<script>
(function() {
  let numeradorObjetivo = 0;
  let denominadorObjetivo = 0;
  let porcionesColoreadas = 0;

  function renderFraccion(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function generarUnSVG(den) {
    let svg = '<svg class="svg-shape" width="140" height="140" viewBox="-75 -75 150 150" style="transform: rotate(-90deg); overflow: visible;">';

    if (den === 1) {
      svg += `<circle cx="0" cy="0" r="70" fill="#f8fafc" stroke="#334155" stroke-width="3" class="slice" data-selected="false" style="cursor:pointer; transition: fill 0.2s;"></circle>`;
    } else {
      let angulo = (2 * Math.PI) / den;
      for (let i = 0; i < den; i++) {
        let a1 = i * angulo;
        let a2 = (i + 1) * angulo;
        let x1 = 70 * Math.cos(a1);
        let y1 = 70 * Math.sin(a1);
        let x2 = 70 * Math.cos(a2);
        let y2 = 70 * Math.sin(a2);

        let largeArc = (a2 - a1) > Math.PI ? 1 : 0;
        let pathData = `M 0 0 L ${x1} ${y1} A 70 70 0 ${largeArc} 1 ${x2} ${y2} Z`;

        svg += `<path d="${pathData}" fill="#f8fafc" stroke="#334155" stroke-width="3" class="slice" data-selected="false" style="cursor:pointer; transition: fill 0.2s;"></path>`;
      }
    }
    svg += '</svg>';
    return svg;
  }

  function generarNuevoEjercicio() {
    // Generar denominador (2 a 6 para evitar hacinamiento visual)
    denominadorObjetivo = Math.floor(Math.random() * 5) + 2;

    // Generar un número de formas enteras aleatorio (entre 2 y 4 formas máximas)
    let maxShapes = Math.floor(Math.random() * 3) + 2; 
    let minNum = denominadorObjetivo + 1; // Siempre mayor a 1 para ser impropia
    let maxNum = (denominadorObjetivo * maxShapes) - 1; // Para que no quede exactamente en un entero sin residuo a veces

    numeradorObjetivo = Math.floor(Math.random() * (maxNum - minNum + 1)) + minNum;

    // Dibujaremos siempre el número estricto de figuras necesarias para contener la fracción
    let numFiguras = Math.ceil(numeradorObjetivo / denominadorObjetivo);
    porcionesColoreadas = 0;

    document.getElementById('disp-fraccion-impropia').innerHTML = renderFraccion(numeradorObjetivo, denominadorObjetivo);

    let htmlFiguras = '';
    for (let i = 0; i < numFiguras; i++) {
      htmlFiguras += generarUnSVG(denominadorObjetivo);
    }
    document.getElementById('svg-container-impropia').innerHTML = htmlFiguras;

    let fb = document.getElementById('fb-mensaje-impropia');
    fb.innerHTML = '';
    fb.style.color = '';

    document.getElementById('btn-comprobar-impropia').disabled = false;
    document.getElementById('btn-comprobar-impropia').style.opacity = '1';
  }

  function interactuarPorcion(e) {
    let target = e.target;
    if (target && target.getAttribute('data-selected') !== null) {
      let isSelected = target.getAttribute('data-selected') === 'true';

      if (!isSelected) {
        target.setAttribute('fill', '#0ea5e9'); 
        target.setAttribute('data-selected', 'true');
        porcionesColoreadas++;
      } else {
        target.setAttribute('fill', '#f8fafc'); 
        target.setAttribute('data-selected', 'false');
        porcionesColoreadas--;
      }
    }
  }

  function comprobarResultado() {
    let fb = document.getElementById('fb-mensaje-impropia');
    if (porcionesColoreadas === numeradorObjetivo) {
      fb.style.color = '#10b981';
      fb.innerHTML = '✓ ¡Correcto! Has formado la fracción impropia coloreando unidades enteras y el resto.';
      document.getElementById('btn-comprobar-impropia').disabled = true;
      document.getElementById('btn-comprobar-impropia').style.opacity = '0.5';
    } else {
      fb.style.color = '#ef4444';
      let exceso = porcionesColoreadas > numeradorObjetivo;
      fb.innerHTML = `✗ Incorrecto. Llevas ${porcionesColoreadas} porciones. ${exceso ? 'Te has pasado.' : 'Sigue coloreando.'}`;
    }
  }

  function inicializarEventos() {
    document.getElementById('btn-nueva-impropia').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-impropia').addEventListener('click', comprobarResultado);
    document.getElementById('svg-container-impropia').addEventListener('click', interactuarPorcion);
    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

