<div id="frac-tutor-doble" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">Calcula el Denominador y Colorea</h3>
<button id="btn-nuevo-doble" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 20px;">Cuenta las partes de la figura para escribir el denominador y colorea las porciones indicadas:</p>
<div style="display: flex; justify-content: center; align-items: center; gap: 40px; flex-wrap: wrap;"><!-- Fracción con input -->
<div id="disp-fraccion-doble" style="background: #f8fafc; padding: 20px 30px; border-radius: 12px; border: 2px solid #cbd5e1; box-shadow: 0 4px 6px rgba(0,0,0,0.05);"><!-- Se inyecta por JS --></div>
<!-- Gráfico interactivo SVG -->
<div id="svg-container-doble" style="display: flex; justify-content: center; align-items: center;"><!-- Se inyecta por JS --></div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-doble" class="frac-btn frac-btn-check">Comprobar Resultado</button>
<div id="fb-mensaje-doble" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 28px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  let numeradorObjetivo = 0;
  let denominadorObjetivo = 0;
  let porcionesColoreadas = 0;

  function renderFraccionInteractiva(n) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <input type="number" id="input-denominador" class="f-input-den" min="1" max="20" placeholder="?">
      </span>
    `;
  }

  function generarGraficoSVG(den) {
    let svg = '<svg width="220" height="220" viewBox="-110 -110 220 220" style="transform: rotate(-90deg); overflow: visible; drop-shadow: 0 4px 6px rgba(0,0,0,0.1);">';

    if (den === 1) {
      svg += `<circle cx="0" cy="0" r="100" fill="#ffffff" stroke="#334155" stroke-width="3" class="slice" data-selected="false" style="cursor:pointer; transition: fill 0.2s;"></circle>`;
    } else {
      let angulo = (2 * Math.PI) / den;
      for (let i = 0; i < den; i++) {
        let a1 = i * angulo;
        let a2 = (i + 1) * angulo;
        let x1 = 100 * Math.cos(a1);
        let y1 = 100 * Math.sin(a1);
        let x2 = 100 * Math.cos(a2);
        let y2 = 100 * Math.sin(a2);

        let largeArc = (a2 - a1) > Math.PI ? 1 : 0;
        let pathData = `M 0 0 L ${x1} ${y1} A 100 100 0 ${largeArc} 1 ${x2} ${y2} Z`;

        svg += `<path d="${pathData}" fill="#ffffff" stroke="#334155" stroke-width="3" class="slice" data-selected="false" style="cursor:pointer; transition: fill 0.2s;"></path>`;
      }
    }
    svg += '</svg>';
    return svg;
  }

  function generarNuevoEjercicio() {
    denominadorObjetivo = Math.floor(Math.random() * 9) + 2; // Entre 2 y 10
    numeradorObjetivo = Math.floor(Math.random() * denominadorObjetivo) + 1; // Entre 1 y el denominador
    porcionesColoreadas = 0;

    document.getElementById('disp-fraccion-doble').innerHTML = renderFraccionInteractiva(numeradorObjetivo);
    document.getElementById('svg-container-doble').innerHTML = generarGraficoSVG(denominadorObjetivo);

    let fb = document.getElementById('fb-mensaje-doble');
    fb.innerHTML = '';
    fb.style.color = '';

    document.getElementById('btn-comprobar-doble').disabled = false;
    document.getElementById('btn-comprobar-doble').style.opacity = '1';
  }

  function interactuarPorcion(e) {
    let target = e.target;
    if (target && target.getAttribute('data-selected') !== null) {
      let isSelected = target.getAttribute('data-selected') === 'true';

      if (!isSelected) {
        target.setAttribute('fill', '#0ea5e9'); 
        target.setAttribute('data-selected', 'true');
        porcionesColoreadas++;
      } else {
        target.setAttribute('fill', '#ffffff'); 
        target.setAttribute('data-selected', 'false');
        porcionesColoreadas--;
      }
    }
  }

  function comprobarResultado() {
    let inputEl = document.getElementById('input-denominador');
    let valDenominador = parseInt(inputEl.value);
    let fb = document.getElementById('fb-mensaje-doble');

    let denomCorrecto = (valDenominador === denominadorObjetivo);
    let colorCorrecto = (porcionesColoreadas === numeradorObjetivo);

    if (denomCorrecto && colorCorrecto) {
      fb.style.color = '#10b981';
      fb.innerHTML = '✓ ¡Excelente! Has identificado el denominador (' + denominadorObjetivo + ') y coloreado la fracción correctamente.';
      document.getElementById('btn-comprobar-doble').disabled = true;
      document.getElementById('btn-comprobar-doble').style.opacity = '0.5';
      inputEl.disabled = true;
      inputEl.style.background = '#d1fae5';
      inputEl.style.borderColor = '#10b981';
      inputEl.style.color = '#065f46';
    } else {
      fb.style.color = '#ef4444';
      let mensajes = [];

      if (isNaN(valDenominador)) {
        mensajes.push("Falta escribir el denominador.");
      } else if (!denomCorrecto) {
        mensajes.push("El denominador es incorrecto (cuenta bien las divisiones de la figura).");
      }

      if (!colorCorrecto) {
        let exceso = porcionesColoreadas > numeradorObjetivo;
        mensajes.push(`Has coloreado ${porcionesColoreadas} porcion${porcionesColoreadas === 1 ? 'es' : 'es'}. ${exceso ? 'Te has pasado.' : 'Te faltan porciones.'}`);
      }

      fb.innerHTML = '✗ Revisa tu respuesta:<br><span style="font-size:1rem; font-weight:600;">' + mensajes.join('<br>') + '</span>';
    }
  }

  function inicializarEventos() {
    document.getElementById('btn-nuevo-doble').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-doble').addEventListener('click', comprobarResultado);
    document.getElementById('svg-container-doble').addEventListener('click', interactuarPorcion);
    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
