<div id="frac-eq-colorear" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">Colorea y Compara</h3>
<button id="btn-nuevo-eq" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 20px;">Colorea ambas fracciones para comprobar que son equivalentes y representan la misma cantidad:</p>
<div style="display: flex; justify-content: center; align-items: stretch; gap: 20px; flex-wrap: wrap; max-width: 700px; margin: 0 auto;"><!-- Fracción 1 -->
<div class="frac-container">
<div id="disp-frac1"></div>
<div id="svg-container-1" style="display: flex; justify-content: center; align-items: center;"></div>
</div>
<!-- Signo Igual -->
<div style="display: flex; align-items: center; justify-content: center; font-size: 3rem; font-weight: bold; color: #94a3b8; padding: 0 10px;">=</div>
<!-- Fracción 2 -->
<div class="frac-container">
<div id="disp-frac2"></div>
<div id="svg-container-2" style="display: flex; justify-content: center; align-items: center;"></div>
</div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-eq" class="frac-btn frac-btn-check">Comprobar Equivalencia</button>
<div id="fb-mensaje-eq" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 56px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  // Base de datos de ejercicios del cuaderno
  const paresEquivalentes = [
    {n1: 1, d1: 2, n2: 2, d2: 4},
    {n1: 1, d1: 3, n2: 2, d2: 6},
    {n1: 2, d1: 4, n2: 4, d2: 8},
    {n1: 1, d1: 2, n2: 4, d2: 8},
    {n1: 1, d1: 3, n2: 3, d2: 9},
    {n1: 2, d1: 5, n2: 4, d2: 10},
    {n1: 2, d1: 3, n2: 4, d2: 6},
    {n1: 1, d1: 4, n2: 2, d2: 8},
    {n1: 1, d1: 2, n2: 3, d2: 6},
    {n1: 3, d1: 4, n2: 6, d2: 8},
    {n1: 1, d1: 5, n2: 2, d2: 10},
    {n1: 3, d1: 5, n2: 6, d2: 10},
    {n1: 4, d1: 5, n2: 8, d2: 10},
    {n1: 1, d1: 3, n2: 2, d2: 6}
  ];

  let ejercicioActual = null;
  let porcionesColoreadas1 = 0;
  let porcionesColoreadas2 = 0;

  function renderFraccion(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function generarGraficoSVG(den, idGrafico) {
    let svg = `<svg width="160" height="160" viewBox="-85 -85 170 170" style="transform: rotate(-90deg); overflow: visible; drop-shadow: 0 4px 6px rgba(0,0,0,0.05);">`;

    let angulo = (2 * Math.PI) / den;
    for (let i = 0; i < den; i++) {
      let a1 = i * angulo;
      let a2 = (i + 1) * angulo;
      let x1 = 80 * Math.cos(a1);
      let y1 = 80 * Math.sin(a1);
      let x2 = 80 * Math.cos(a2);
      let y2 = 80 * Math.sin(a2);

      let largeArc = (a2 - a1) > Math.PI ? 1 : 0;
      let pathData = `M 0 0 L ${x1} ${y1} A 80 80 0 ${largeArc} 1 ${x2} ${y2} Z`;

      svg += `<path d="${pathData}" fill="#ffffff" stroke="#334155" stroke-width="2.5" class="slice" data-selected="false" data-grafico="${idGrafico}" style="cursor:pointer; transition: fill 0.2s;"></path>`;
    }
    svg += '</svg>';
    return svg;
  }

  function generarNuevoEjercicio() {
    ejercicioActual = paresEquivalentes[Math.floor(Math.random() * paresEquivalentes.length)];

    // Aleatorizar qué fracción va a la izquierda o derecha
    if (Math.random() > 0.5) {
      ejercicioActual = { n1: ejercicioActual.n2, d1: ejercicioActual.d2, n2: ejercicioActual.n1, d2: ejercicioActual.d1 };
    }

    porcionesColoreadas1 = 0;
    porcionesColoreadas2 = 0;

    document.getElementById('disp-frac1').innerHTML = renderFraccion(ejercicioActual.n1, ejercicioActual.d1);
    document.getElementById('disp-frac2').innerHTML = renderFraccion(ejercicioActual.n2, ejercicioActual.d2);

    document.getElementById('svg-container-1').innerHTML = generarGraficoSVG(ejercicioActual.d1, 1);
    document.getElementById('svg-container-2').innerHTML = generarGraficoSVG(ejercicioActual.d2, 2);

    let fb = document.getElementById('fb-mensaje-eq');
    fb.innerHTML = '';
    fb.style.color = '';

    document.getElementById('btn-comprobar-eq').disabled = false;
    document.getElementById('btn-comprobar-eq').style.opacity = '1';
  }

  function interactuarPorcion(e) {
    let target = e.target;
    if (target && target.getAttribute('data-selected') !== null) {
      let isSelected = target.getAttribute('data-selected') === 'true';
      let idGrafico = parseInt(target.getAttribute('data-grafico'));

      if (!isSelected) {
        target.setAttribute('fill', '#0ea5e9'); 
        target.setAttribute('data-selected', 'true');
        if (idGrafico === 1) porcionesColoreadas1++;
        if (idGrafico === 2) porcionesColoreadas2++;
      } else {
        target.setAttribute('fill', '#ffffff'); 
        target.setAttribute('data-selected', 'false');
        if (idGrafico === 1) porcionesColoreadas1--;
        if (idGrafico === 2) porcionesColoreadas2--;
      }
    }
  }

  function comprobarResultado() {
    let fb = document.getElementById('fb-mensaje-eq');

    let ok1 = (porcionesColoreadas1 === ejercicioActual.n1);
    let ok2 = (porcionesColoreadas2 === ejercicioActual.n2);

    if (ok1 && ok2) {
      fb.style.color = '#10b981';
      fb.innerHTML = '✓ ¡Excelente! Has coloreado ambas fracciones correctamente. Observa cómo, a pesar de tener números distintos, el área sombreada en las dos figuras es idéntica.';
      document.getElementById('btn-comprobar-eq').disabled = true;
      document.getElementById('btn-comprobar-eq').style.opacity = '0.5';
    } else {
      fb.style.color = '#ef4444';
      let mensaje = '✗ Incorrecto.<br>';

      if (!ok1) {
        mensaje += `En la primera figura has coloreado ${porcionesColoreadas1} porcion${porcionesColoreadas1 === 1 ? 'es' : 'es'}, y deberías colorear ${ejercicioActual.n1}.<br>`;
      }
      if (!ok2) {
        mensaje += `En la segunda figura has coloreado ${porcionesColoreadas2} porcion${porcionesColoreadas2 === 1 ? 'es' : 'es'}, y deberías colorear ${ejercicioActual.n2}.`;
      }

      fb.innerHTML = `<span style="font-size:1rem; font-weight:600;">${mensaje}</span>`;
    }
  }

  function inicializarEventos() {
    document.getElementById('btn-nuevo-eq').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-eq').addEventListener('click', comprobarResultado);

    document.getElementById('svg-container-1').addEventListener('click', interactuarPorcion);
    document.getElementById('svg-container-2').addEventListener('click', interactuarPorcion);

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

