  </style>
<div id="frac-eq-vf" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">Detector de Equivalencias</h3>
<button id="btn-nuevo-vf" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 30px;">¿Son equivalentes las siguientes fracciones?</p>
<div style="display: flex; justify-content: center; align-items: center; gap: 30px; margin-bottom: 30px; background: #f8fafc; padding: 30px; border-radius: 12px; border: 2px solid #cbd5e1; box-shadow: 0 4px 6px rgba(0,0,0,0.05); max-width: 400px; margin-left: auto; margin-right: auto;">
<div id="disp-frac1-vf"></div>
<div style="font-size: 1.5rem; font-weight: bold; color: #64748b;">y</div>
<div id="disp-frac2-vf"></div>
</div>
<!-- Botones de decisión -->
<div style="display: flex; justify-content: center; gap: 15px; flex-wrap: wrap;" id="zona-botones-vf"><button id="btn-yes-vf" class="frac-btn btn-yes">Sí, son equivalentes</button> <button id="btn-no-vf" class="frac-btn btn-no">No, no lo son</button></div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;">
<div id="fb-mensaje-vf" style="font-weight: bold; font-size: 1.15rem; min-height: 70px; line-height: 1.5;"></div>
</div>
</div>
<p>
<script>
(function() {
  // Base de datos de ejercicios extraída del cuaderno
  const ejerciciosVF = [
    {n1: 4, d1: 5, n2: 7, d2: 9},
    {n1: 6, d1: 15, n2: 2, d2: 5},
    {n1: 2, d1: 6, n2: 8, d2: 24},
    {n1: 10, d1: 5, n2: 12, d2: 6},
    {n1: 4, d1: 9, n2: 36, d2: 81},
    {n1: 6, d1: 42, n2: 11, d2: 66},
    {n1: 1, d1: 4, n2: 3, d2: 12},
    {n1: 2, d1: 5, n2: 6, d2: 14},
    {n1: 8, d1: 15, n2: 5, d2: 9},
    {n1: 1, d1: 8, n2: 5, d2: 40},
    {n1: 3, d1: 4, n2: 9, d2: 16},
    {n1: 2, d1: 16, n2: 7, d2: 56}
  ];

  let ejercicioActual = null;
  let botonesActivos = true;

  function renderFraccion(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function generarNuevoEjercicio() {
    ejercicioActual = ejerciciosVF[Math.floor(Math.random() * ejerciciosVF.length)];

    // Aleatorizar posición izquierda/derecha para mayor variedad
    if (Math.random() > 0.5) {
      ejercicioActual = { n1: ejercicioActual.n2, d1: ejercicioActual.d2, n2: ejercicioActual.n1, d2: ejercicioActual.d1 };
    }

    document.getElementById('disp-frac1-vf').innerHTML = renderFraccion(ejercicioActual.n1, ejercicioActual.d1);
    document.getElementById('disp-frac2-vf').innerHTML = renderFraccion(ejercicioActual.n2, ejercicioActual.d2);

    let fb = document.getElementById('fb-mensaje-vf');
    fb.innerHTML = '';

    document.getElementById('btn-yes-vf').disabled = false;
    document.getElementById('btn-yes-vf').style.opacity = '1';
    document.getElementById('btn-no-vf').disabled = false;
    document.getElementById('btn-no-vf').style.opacity = '1';
    botonesActivos = true;
  }

  function evaluarRespuesta(respuestaAlumno) {
    if (!botonesActivos) return;
    botonesActivos = false;

    // Desactivar botones temporalmente
    document.getElementById('btn-yes-vf').disabled = true;
    document.getElementById('btn-yes-vf').style.opacity = '0.5';
    document.getElementById('btn-no-vf').disabled = true;
    document.getElementById('btn-no-vf').style.opacity = '0.5';

    let n1 = ejercicioActual.n1, d1 = ejercicioActual.d1;
    let n2 = ejercicioActual.n2, d2 = ejercicioActual.d2;

    let prod1 = n1 * d2;
    let prod2 = n2 * d1;
    let sonEquivalentes = (prod1 === prod2);

    let esCorrecto = (respuestaAlumno === sonEquivalentes);
    let fb = document.getElementById('fb-mensaje-vf');

    let justificacionHTML = `
      <div style="margin-top: 10px; background: #f8fafc; padding: 10px; border-radius: 8px; border: 1px solid #e2e8f0; display: inline-block; text-align: left; color: #334155;">
        <div style="font-size: 0.95rem; margin-bottom: 5px;">Comprobación por productos cruzados:</div>
        <div style="font-family: monospace; font-size: 1.1rem;">
          ${n1} × ${d2} = <strong>${prod1}</strong><br>
          ${n2} × ${d1} = <strong>${prod2}</strong>
        </div>
      </div>
    `;

    if (esCorrecto) {
      fb.innerHTML = `<span style="color: #10b981;">✓ ¡Correcto!</span> Has acertado.<br>${justificacionHTML}`;
    } else {
      fb.innerHTML = `<span style="color: #ef4444;">✗ Incorrecto.</span> La respuesta era ${sonEquivalentes ? 'Sí' : 'No'}.<br>${justificacionHTML}`;
    }
  }

  function inicializarEventos() {
    document.getElementById('btn-nuevo-vf').addEventListener('click', generarNuevoEjercicio);

    document.getElementById('btn-yes-vf').addEventListener('click', function() {
      evaluarRespuesta(true);
    });

    document.getElementById('btn-no-vf').addEventListener('click', function() {
      evaluarRespuesta(false);
    });

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

