<div id="frac-eq-completa" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">Completa la Fracción Equivalente</h3>
<button id="btn-nuevo-com" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 30px;">Averigua la relación de proporcionalidad y escribe el número que falta:</p>
<div style="display: flex; justify-content: center; align-items: center; gap: 20px; flex-wrap: wrap; background: #f8fafc; padding: 30px; border-radius: 12px; border: 2px solid #cbd5e1; box-shadow: 0 4px 6px rgba(0,0,0,0.05); max-width: 500px; margin: 0 auto;">
<div id="disp-frac1-com"></div>
<div style="font-size: 3rem; font-weight: bold; color: #94a3b8; padding: 0 10px;">=</div>
<div id="disp-frac2-com"></div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-com" class="frac-btn frac-btn-check">Comprobar Resultado</button>
<div id="fb-mensaje-com" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 28px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  // Base de datos de ejercicios de completar extraída del cuaderno
  const ejerciciosCompletar = [
    {n1: null, d1: 4, n2: 7, d2: 28},
    {n1: 2, d1: 6, n2: null, d2: 30},
    {n1: 5, d1: null, n2: 45, d2: 18},
    {n1: 1, d1: 8, n2: null, d2: 48},
    {n1: 3, d1: 6, n2: 12, d2: null},
    {n1: null, d1: 16, n2: 20, d2: 80},
    {n1: null, d1: 4, n2: 7, d2: 28},
    {n1: 2, d1: 6, n2: null, d2: 30},
    {n1: 5, d1: null, n2: 45, d2: 18},
    {n1: 2, d1: 5, n2: null, d2: 15},
    {n1: 3, d1: 7, n2: 6, d2: null},
    {n1: null, d1: 8, n2: 9, d2: 24}
  ];

  let ejercicioActual = null;
  let valorCorrecto = 0;

  function renderFraccionEstatica(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function renderFraccionConInput(n, d) {
    let htmlNum = n !== null ? `<span class="f-num">${n}</span>` : `<input type="number" id="input-termino" class="f-input" placeholder="?">`;
    let htmlDen = d !== null ? `<span class="f-den">${d}</span>` : `<input type="number" id="input-termino" class="f-input" placeholder="?">`;

    return `
      <span class="frac-box">
        ${htmlNum}
        <span class="f-line"></span>
        ${htmlDen}
      </span>
    `;
  }

  function resolverTerminoFaltante(ej) {
    if (ej.n1 === null) return (ej.d1 * ej.n2) / ej.d2;
    if (ej.d1 === null) return (ej.n1 * ej.d2) / ej.n2;
    if (ej.n2 === null) return (ej.n1 * ej.d2) / ej.d1;
    if (ej.d2 === null) return (ej.d1 * ej.n2) / ej.n1;
    return 0;
  }

  function generarNuevoEjercicio() {
    ejercicioActual = ejerciciosCompletar[Math.floor(Math.random() * ejerciciosCompletar.length)];
    valorCorrecto = resolverTerminoFaltante(ejercicioActual);

    let htmlFrac1 = (ejercicioActual.n1 === null || ejercicioActual.d1 === null) 
      ? renderFraccionConInput(ejercicioActual.n1, ejercicioActual.d1)
      : renderFraccionEstatica(ejercicioActual.n1, ejercicioActual.d1);

    let htmlFrac2 = (ejercicioActual.n2 === null || ejercicioActual.d2 === null) 
      ? renderFraccionConInput(ejercicioActual.n2, ejercicioActual.d2)
      : renderFraccionEstatica(ejercicioActual.n2, ejercicioActual.d2);

    // Permitir invertir aleatoriamente la izquierda y derecha
    if (Math.random() > 0.5) {
      document.getElementById('disp-frac1-com').innerHTML = htmlFrac2;
      document.getElementById('disp-frac2-com').innerHTML = htmlFrac1;
    } else {
      document.getElementById('disp-frac1-com').innerHTML = htmlFrac1;
      document.getElementById('disp-frac2-com').innerHTML = htmlFrac2;
    }

    let fb = document.getElementById('fb-mensaje-com');
    fb.innerHTML = '';

    document.getElementById('btn-comprobar-com').disabled = false;
    document.getElementById('btn-comprobar-com').style.opacity = '1';

    // Soporte para tecla Enter
    let inputEl = document.getElementById('input-termino');
    if (inputEl) {
      inputEl.addEventListener('keypress', function(e) {
        if (e.key === 'Enter') comprobarResultado();
      });
      inputEl.focus();
    }
  }

  function comprobarResultado() {
    let inputEl = document.getElementById('input-termino');
    let valUsuario = parseInt(inputEl.value);
    let fb = document.getElementById('fb-mensaje-com');

    if (isNaN(valUsuario)) {
      fb.style.color = '#ef4444';
      fb.innerHTML = '✗ Falta escribir el número.';
      return;
    }

    if (valUsuario === valorCorrecto) {
      fb.style.color = '#10b981';
      fb.innerHTML = '✓ ¡Correcto! Has encontrado el término equivalente.';
      document.getElementById('btn-comprobar-com').disabled = true;
      document.getElementById('btn-comprobar-com').style.opacity = '0.5';
      inputEl.disabled = true;
      inputEl.style.background = '#d1fae5';
      inputEl.style.borderColor = '#10b981';
      inputEl.style.color = '#065f46';
    } else {
      fb.style.color = '#ef4444';
      fb.innerHTML = `✗ Incorrecto. Pista: Fíjate por qué número se ha multiplicado o dividido la otra parte de la fracción.`;
    }
  }

  function inicializarEventos() {
    document.getElementById('btn-nuevo-com').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-com').addEventListener('click', comprobarResultado);
    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

