  </style>
<div id="frac-amp-simp" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">La Máquina de Amplificar / Simplificar</h3>
<div style="display: flex; gap: 10px;"><button id="btn-nuevo-amp" class="frac-btn" style="background-color: #f59e0b !important; border-color: #d97706 !important;">Amplificar</button> <button id="btn-nuevo-simp" class="frac-btn" style="background-color: #8b5cf6 !important; border-color: #7c3aed !important;">Simplificar</button></div>
</div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p id="instruccion-amp-simp" style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 30px;">Averigua por qué número se ha multiplicado para obtener la fracción equivalente:</p>
<div style="display: flex; justify-content: center; align-items: center; gap: 20px; flex-wrap: wrap; background: #f8fafc; padding: 30px; border-radius: 12px; border: 2px solid #cbd5e1; box-shadow: 0 4px 6px rgba(0,0,0,0.05); max-width: 500px; margin: 0 auto;">
<div id="disp-frac1-maquina"></div>
<div class="operacion-columna">
<div style="display: flex; align-items: center; gap: 5px;"><span id="signo-operacion-num" style="font-size: 1.5rem; font-weight: bold; color: #64748b;">x</span> <input type="number" id="input-factor-num" class="f-input" placeholder="?" /></div>
<div style="font-size: 2rem; font-weight: bold; color: #94a3b8;">→</div>
<div style="display: flex; align-items: center; gap: 5px;"><span id="signo-operacion-den" style="font-size: 1.5rem; font-weight: bold; color: #64748b;">x</span> <input type="number" id="input-factor-den" class="f-input" placeholder="?" /></div>
</div>
<div id="disp-frac2-maquina"></div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-maquina" class="frac-btn frac-btn-check">Comprobar Resultado</button>
<div id="fb-mensaje-maquina" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 28px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  const paresAmplificacion = [
    {n1: 1, d1: 3, factor: 2},
    {n1: 2, d1: 5, factor: 2},
    {n1: 3, d1: 4, factor: 2},
    {n1: 5, d1: 6, factor: 2},
    {n1: 4, d1: 9, factor: 2},
    {n1: 7, d1: 8, factor: 2},
    {n1: 7, d1: 4, factor: 2},
    {n1: 5, d1: 3, factor: 2},
    {n1: 2, d1: 6, factor: 2},
    {n1: 1, d1: 8, factor: 2},
    {n1: 3, d1: 5, factor: 2},
    {n1: 6, d1: 9, factor: 2},
    {n1: 6, d1: 2, factor: 2},
    {n1: 9, d1: 3, factor: 2},
    {n1: 4, d1: 7, factor: 2},
    {n1: 2, d1: 4, factor: 2},
    {n1: 3, d1: 6, factor: 2},
    {n1: 4, d1: 5, factor: 2}
  ];

  const paresSimplificacion = [
    {n1: 15, d1: 20, factor: 5},
    {n1: 12, d1: 10, factor: 2},
    {n1: 24, d1: 12, factor: 12},
    {n1: 90, d1: 60, factor: 30},
    {n1: 96, d1: 144, factor: 48},
    {n1: 100, d1: 60, factor: 20},
    {n1: 28, d1: 56, factor: 28},
    {n1: 81, d1: 27, factor: 27},
    {n1: 240, d1: 200, factor: 40},
    {n1: 224, d1: 256, factor: 32},
    {n1: 30, d1: 24, factor: 6},
    {n1: 20, d1: 180, factor: 20},
    {n1: 84, d1: 126, factor: 42},
    {n1: 108, d1: 180, factor: 36},
    {n1: 100, d1: 50, factor: 50},
    {n1: 144, d1: 96, factor: 48},
    {n1: 28, d1: 42, factor: 14},
    {n1: 180, d1: 180, factor: 180},
    {n1: 80, d1: 30, factor: 10}
  ];

  let modoActual = 'amp'; // 'amp' o 'simp'
  let factorCorrecto = 0;

  function renderFraccionEstatica(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function generarNuevoEjercicio(modo) {
    modoActual = modo;
    let ejercicio;

    if (modo === 'amp') {
        ejercicio = paresAmplificacion[Math.floor(Math.random() * paresAmplificacion.length)];
        // Para dar más variedad, cambiamos el factor a veces
        let factorAleatorio = Math.floor(Math.random() * 5) + 2; 
        factorCorrecto = factorAleatorio;

        let n2 = ejercicio.n1 * factorAleatorio;
        let d2 = ejercicio.d1 * factorAleatorio;

        document.getElementById('instruccion-amp-simp').textContent = 'Averigua por qué número se ha multiplicado para obtener la fracción equivalente (Amplificación):';
        document.getElementById('signo-operacion-num').textContent = 'x';
        document.getElementById('signo-operacion-den').textContent = 'x';

        document.getElementById('disp-frac1-maquina').innerHTML = renderFraccionEstatica(ejercicio.n1, ejercicio.d1);
        document.getElementById('disp-frac2-maquina').innerHTML = renderFraccionEstatica(n2, d2);

    } else {
        ejercicio = paresSimplificacion[Math.floor(Math.random() * paresSimplificacion.length)];
        factorCorrecto = ejercicio.factor;

        let n2 = ejercicio.n1 / ejercicio.factor;
        let d2 = ejercicio.d1 / ejercicio.factor;

        document.getElementById('instruccion-amp-simp').textContent = 'Averigua por qué número se ha dividido para obtener la fracción equivalente (Simplificación):';
        document.getElementById('signo-operacion-num').textContent = ':';
        document.getElementById('signo-operacion-den').textContent = ':';

        document.getElementById('disp-frac1-maquina').innerHTML = renderFraccionEstatica(ejercicio.n1, ejercicio.d1);
        document.getElementById('disp-frac2-maquina').innerHTML = renderFraccionEstatica(n2, d2);
    }

    let inputNum = document.getElementById('input-factor-num');
    let inputDen = document.getElementById('input-factor-den');

    inputNum.value = '';
    inputDen.value = '';
    inputNum.disabled = false;
    inputDen.disabled = false;
    inputNum.style.background = '#f8fafc';
    inputDen.style.background = '#f8fafc';
    inputNum.style.borderColor = '#94a3b8';
    inputDen.style.borderColor = '#94a3b8';

    let fb = document.getElementById('fb-mensaje-maquina');
    fb.innerHTML = '';

    document.getElementById('btn-comprobar-maquina').disabled = false;
    document.getElementById('btn-comprobar-maquina').style.opacity = '1';
  }

  function comprobarResultado() {
    let inputNum = document.getElementById('input-factor-num');
    let inputDen = document.getElementById('input-factor-den');

    let valNum = parseInt(inputNum.value);
    let valDen = parseInt(inputDen.value);
    let fb = document.getElementById('fb-mensaje-maquina');

    if (isNaN(valNum) || isNaN(valDen)) {
      fb.style.color = '#ef4444';
      fb.innerHTML = '✗ Faltan números por escribir.';
      return;
    }

    if (valNum === factorCorrecto && valDen === factorCorrecto) {
      fb.style.color = '#10b981';
      fb.innerHTML = '✓ ¡Correcto! Has encontrado el factor.';
      document.getElementById('btn-comprobar-maquina').disabled = true;
      document.getElementById('btn-comprobar-maquina').style.opacity = '0.5';
      inputNum.disabled = true;
      inputDen.disabled = true;
      inputNum.style.background = '#d1fae5';
      inputDen.style.background = '#d1fae5';
      inputNum.style.borderColor = '#10b981';
      inputDen.style.borderColor = '#10b981';
    } else {
      fb.style.color = '#ef4444';
      if (valNum !== valDen) {
         fb.innerHTML = `✗ Recuerda que para obtener una fracción equivalente debes ${modoActual === 'amp' ? 'multiplicar' : 'dividir'} arriba y abajo por el <strong>mismo</strong> número.`;
      } else {
         fb.innerHTML = `✗ Incorrecto. Revisa tus cálculos.`;
      }
    }
  }

  function inicializarEventos() {
    document.getElementById('btn-nuevo-amp').addEventListener('click', () => generarNuevoEjercicio('amp'));
    document.getElementById('btn-nuevo-simp').addEventListener('click', () => generarNuevoEjercicio('simp'));
    document.getElementById('btn-comprobar-maquina').addEventListener('click', comprobarResultado);

    let inputDen = document.getElementById('input-factor-den');
    inputDen.addEventListener('keypress', function(e) {
        if (e.key === 'Enter') comprobarResultado();
    });

    generarNuevoEjercicio('amp');
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

