<div id="frac-cruzados" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">Reducción por Productos Cruzados</h3>
<button id="btn-nuevo-cruz" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 30px;">Reduce a común denominador operando en cruz y completa las nuevas fracciones:</p>
<div style="display: flex; justify-content: center; align-items: center; gap: 20px; flex-wrap: wrap; background: #f8fafc; padding: 30px; border-radius: 12px; border: 2px solid #cbd5e1; box-shadow: 0 4px 6px rgba(0,0,0,0.05); max-width: 800px; margin: 0 auto;"><!-- Fracciones iniciales -->
<div id="disp-frac1-cruz"></div>
<div style="font-size: 1.5rem; font-weight: bold; color: #64748b;">y</div>
<div id="disp-frac2-cruz"></div>
<div style="font-size: 2.5rem; font-weight: bold; color: #94a3b8; padding: 0 15px;">→</div>
<!-- Fracciones resultantes interactivas --> <span class="frac-box"> <input type="number" id="inp-n1-cruz" class="f-input" placeholder="?" /> <span class="f-line"></span> <input type="number" id="inp-d1-cruz" class="f-input" placeholder="?" /> </span>
<div style="font-size: 1.5rem; font-weight: bold; color: #64748b;">y</div>
<span class="frac-box"> <input type="number" id="inp-n2-cruz" class="f-input" placeholder="?" /> <span class="f-line"></span> <input type="number" id="inp-d2-cruz" class="f-input" placeholder="?" /> </span></div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-cruz" class="frac-btn frac-btn-check">Comprobar Resultado</button>
<div id="fb-mensaje-cruz" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 50px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  let ejercicioActual = {};

  function generarNuevoEjercicio() {
    // Generar 2 fracciones aleatorias con números manejables (entre 2 y 9)
    ejercicioActual.n1 = Math.floor(Math.random() * 8) + 1;
    ejercicioActual.d1 = Math.floor(Math.random() * 8) + 2;

    ejercicioActual.n2 = Math.floor(Math.random() * 8) + 1;
    ejercicioActual.d2 = Math.floor(Math.random() * 8) + 2;

    // Evitar denominadores idénticos de base
    while(ejercicioActual.d1 === ejercicioActual.d2) {
      ejercicioActual.d2 = Math.floor(Math.random() * 8) + 2;
    }

    // Cálculos por productos cruzados
    ejercicioActual.targetD = ejercicioActual.d1 * ejercicioActual.d2;
    ejercicioActual.targetN1 = ejercicioActual.n1 * ejercicioActual.d2;
    ejercicioActual.targetN2 = ejercicioActual.n2 * ejercicioActual.d1;

    // Pintar fracciones originales
    document.getElementById('disp-frac1-cruz').innerHTML = `
      <span class="frac-box">
        <span class="f-num">${ejercicioActual.n1}</span>
        <span class="f-line"></span>
        <span class="f-den">${ejercicioActual.d1}</span>
      </span>
    `;
    document.getElementById('disp-frac2-cruz').innerHTML = `
      <span class="frac-box">
        <span class="f-num">${ejercicioActual.n2}</span>
        <span class="f-line"></span>
        <span class="f-den">${ejercicioActual.d2}</span>
      </span>
    `;

    // Resetear inputs de la UI
    ['inp-n1-cruz', 'inp-d1-cruz', 'inp-n2-cruz', 'inp-d2-cruz'].forEach(id => {
      let el = document.getElementById(id);
      el.value = '';
      el.disabled = false;
      el.style.background = '#f8fafc';
      el.style.borderColor = '#94a3b8';
      el.style.color = '#0284c7';
    });

    let fb = document.getElementById('fb-mensaje-cruz');
    fb.innerHTML = '';

    document.getElementById('btn-comprobar-cruz').disabled = false;
    document.getElementById('btn-comprobar-cruz').style.opacity = '1';
  }

  function comprobarResultado() {
    let in1 = parseInt(document.getElementById('inp-n1-cruz').value);
    let id1 = parseInt(document.getElementById('inp-d1-cruz').value);
    let in2 = parseInt(document.getElementById('inp-n2-cruz').value);
    let id2 = parseInt(document.getElementById('inp-d2-cruz').value);
    let fb = document.getElementById('fb-mensaje-cruz');

    if (isNaN(in1) || isNaN(id1) || isNaN(in2) || isNaN(id2)) {
      fb.style.color = '#ef4444';
      fb.innerHTML = '✗ Faltan números por rellenar.';
      return;
    }

    let okN1 = (in1 === ejercicioActual.targetN1);
    let okD1 = (id1 === ejercicioActual.targetD);
    let okN2 = (in2 === ejercicioActual.targetN2);
    let okD2 = (id2 === ejercicioActual.targetD);

    if (okN1 && okD1 && okN2 && okD2) {
      fb.style.color = '#10b981';
      fb.innerHTML = '✓ ¡Perfecto! Has reducido las fracciones a común denominador aplicando el método de los productos cruzados.';
      document.getElementById('btn-comprobar-cruz').disabled = true;
      document.getElementById('btn-comprobar-cruz').style.opacity = '0.5';

      ['inp-n1-cruz', 'inp-d1-cruz', 'inp-n2-cruz', 'inp-d2-cruz'].forEach(id => {
        let el = document.getElementById(id);
        el.disabled = true;
        el.style.background = '#d1fae5';
        el.style.borderColor = '#10b981';
        el.style.color = '#065f46';
      });
    } else {
      fb.style.color = '#ef4444';
      let msg = '✗ Hay errores en el cálculo.<br><span style="font-size:1rem; font-weight:600;">';

      if (!okD1 || !okD2) {
        msg += `Recuerda: El denominador común es el producto directo de los denominadores (${ejercicioActual.d1} × ${ejercicioActual.d2}).<br>`;
      }
      if (!okN1 || !okN2) {
        msg += `Para los numeradores, multiplica el numerador original por el denominador contrario.`;
      }
      msg += '</span>';
      fb.innerHTML = msg;
    }
  }

  function inicializarEventos() {
    document.getElementById('btn-nuevo-cruz').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-cruz').addEventListener('click', comprobarResultado);

    // Comprobar con la tecla enter desde el último input
    document.getElementById('inp-d2-cruz').addEventListener('keypress', function(e) {
      if (e.key === 'Enter') comprobarResultado();
    });

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

