<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 20px;">Halla el mínimo común múltiplo (m.c.m.) de los denominadores y completa las fracciones equivalentes:</p>
<div style="background: #f8fafc; padding: 25px; border-radius: 12px; border: 2px solid #cbd5e1; box-shadow: 0 4px 6px rgba(0,0,0,0.05); max-width: 800px; margin: 0 auto;"><!-- Fracciones originales -->
<div style="display: flex; justify-content: center; align-items: center; gap: 20px; flex-wrap: wrap; margin-bottom: 20px;">
<div id="disp-frac1-mcm"></div>
<div style="font-size: 1.5rem; font-weight: bold; color: #64748b;">y</div>
<div id="disp-frac2-mcm"></div>
</div>
<!-- Calculo del mcm -->
<div style="font-size: 1.3rem; font-weight: bold; color: #334155; margin-bottom: 25px; background: #e2e8f0; padding: 10px; border-radius: 8px; display: inline-block;">m.c.m. ( <span id="txt-d1"></span> , <span id="txt-d2"></span> ) = <input type="number" id="inp-val-mcm" class="f-input" style="width: 80px !important; margin-left: 10px !important;" placeholder="?" /></div>
<div style="font-size: 2rem; font-weight: bold; color: #94a3b8; margin-bottom: 15px;">↓</div>
<!-- Fracciones resultantes interactivas -->
<div style="display: flex; justify-content: center; align-items: center; gap: 20px; flex-wrap: wrap;"><span class="frac-box"> <input type="number" id="inp-n1-mcm" class="f-input" placeholder="?" /> <span class="f-line"></span> <input type="number" id="inp-d1-mcm" class="f-input" placeholder="?" /> </span>
<div style="font-size: 1.5rem; font-weight: bold; color: #64748b;">y</div>
<span class="frac-box"> <input type="number" id="inp-n2-mcm" class="f-input" placeholder="?" /> <span class="f-line"></span> <input type="number" id="inp-d2-mcm" class="f-input" placeholder="?" /> </span></div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-mcm" class="frac-btn frac-btn-check">Comprobar Resultado</button>
<div id="fb-mensaje-mcm" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 50px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  const paresMcm = [
    [4, 6], [6, 8], [6, 9], [8, 12],
    [10, 15], [12, 18], [15, 20],
    [20, 30], [24, 36], [9, 15]
  ];

  let ej = {};

  function calcularMCD(a, b) {
    return b === 0 ? a : calcularMCD(b, a % b);
  }

  function calcularMCM(a, b) {
    return (a * b) / calcularMCD(a, b);
  }

  function generarNuevoEjercicio() {
    let par = paresMcm[Math.floor(Math.random() * paresMcm.length)];

    ej.d1 = par[0];
    ej.d2 = par[1];

    // Invertir aleatoriamente para más variedad
    if (Math.random() > 0.5) {
      ej.d1 = par[1];
      ej.d2 = par[0];
    }

    ej.n1 = Math.floor(Math.random() * (ej.d1 - 1)) + 1;
    ej.n2 = Math.floor(Math.random() * (ej.d2 - 1)) + 1;

    ej.targetMcm = calcularMCM(ej.d1, ej.d2);
    ej.targetN1 = ej.n1 * (ej.targetMcm / ej.d1);
    ej.targetN2 = ej.n2 * (ej.targetMcm / ej.d2);

    document.getElementById('disp-frac1-mcm').innerHTML = `
      <span class="frac-box">
        <span class="f-num">${ej.n1}</span>
        <span class="f-line"></span>
        <span class="f-den">${ej.d1}</span>
      </span>
    `;
    document.getElementById('disp-frac2-mcm').innerHTML = `
      <span class="frac-box">
        <span class="f-num">${ej.n2}</span>
        <span class="f-line"></span>
        <span class="f-den">${ej.d2}</span>
      </span>
    `;

    document.getElementById('txt-d1').textContent = ej.d1;
    document.getElementById('txt-d2').textContent = ej.d2;

    ['inp-val-mcm', 'inp-n1-mcm', 'inp-d1-mcm', 'inp-n2-mcm', 'inp-d2-mcm'].forEach(id => {
      let el = document.getElementById(id);
      el.value = '';
      el.disabled = false;
      el.style.background = '#f8fafc';
      el.style.borderColor = '#94a3b8';
      el.style.color = '#0284c7';
    });

    let fb = document.getElementById('fb-mensaje-mcm');
    fb.innerHTML = '';

    document.getElementById('btn-comprobar-mcm').disabled = false;
    document.getElementById('btn-comprobar-mcm').style.opacity = '1';
  }

  function comprobarResultado() {
    let iMcm = parseInt(document.getElementById('inp-val-mcm').value);
    let in1 = parseInt(document.getElementById('inp-n1-mcm').value);
    let id1 = parseInt(document.getElementById('inp-d1-mcm').value);
    let in2 = parseInt(document.getElementById('inp-n2-mcm').value);
    let id2 = parseInt(document.getElementById('inp-d2-mcm').value);
    let fb = document.getElementById('fb-mensaje-mcm');

    if (isNaN(iMcm) || isNaN(in1) || isNaN(id1) || isNaN(in2) || isNaN(id2)) {
      fb.style.color = '#ef4444';
      fb.innerHTML = '✗ Faltan números por rellenar.';
      return;
    }

    let okMcm = (iMcm === ej.targetMcm);
    let okD1 = (id1 === ej.targetMcm);
    let okD2 = (id2 === ej.targetMcm);
    let okN1 = (in1 === ej.targetN1);
    let okN2 = (in2 === ej.targetN2);

    if (okMcm && okD1 && okD2 && okN1 && okN2) {
      fb.style.color = '#10b981';
      fb.innerHTML = '✓ ¡Perfecto! Has calculado el m.c.m. y deducido las nuevas fracciones equivalentes.';
      document.getElementById('btn-comprobar-mcm').disabled = true;
      document.getElementById('btn-comprobar-mcm').style.opacity = '0.5';

      ['inp-val-mcm', 'inp-n1-mcm', 'inp-d1-mcm', 'inp-n2-mcm', 'inp-d2-mcm'].forEach(id => {
        let el = document.getElementById(id);
        el.disabled = true;
        el.style.background = '#d1fae5';
        el.style.borderColor = '#10b981';
        el.style.color = '#065f46';
      });
    } else {
      fb.style.color = '#ef4444';
      let msg = '✗ Hay errores en el cálculo.<br><span style="font-size:1rem; font-weight:600;">';

      if (!okMcm) {
        msg += `El m.c.m. de ${ej.d1} y ${ej.d2} es incorrecto. Repasa la descomposición factorial.<br>`;
      } else {
        if (!okD1 || !okD2) {
          msg += `Recuerda: El nuevo denominador en ambas fracciones debe ser exactamente el m.c.m. (${ej.targetMcm}).<br>`;
        }
        if (!okN1 || !okN2) {
          msg += `Para los numeradores, divide el m.c.m. entre el denominador antiguo y multiplica por el numerador original.`;
        }
      }
      msg += '</span>';
      fb.innerHTML = msg;
    }
  }

  function inicializarEventos() {
    document.getElementById('btn-nuevo-mcm').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-mcm').addEventListener('click', comprobarResultado);

    document.getElementById('inp-d2-mcm').addEventListener('keypress', function(e) {
      if (e.key === 'Enter') comprobarResultado();
    });

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
