<div id="frac-criterios" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">Entrenador de Criterios</h3>
<button id="btn-nuevo-crit" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 30px;">Compara las siguientes fracciones e indica si la primera es Mayor (&gt;), Menor (&lt;) o Igual (=):</p>
<div style="display: flex; justify-content: center; align-items: center; gap: 30px; flex-wrap: wrap; background: #f8fafc; padding: 30px; border-radius: 12px; border: 2px solid #cbd5e1; box-shadow: 0 4px 6px rgba(0,0,0,0.05); max-width: 600px; margin: 0 auto;"><!-- Fracción 1 -->
<div id="disp-frac1-crit"></div>
<!-- Botones de decisión -->
<div style="display: flex; gap: 10px;" id="botones-crit"><button class="frac-btn btn-opcion" data-val="&lt;">&lt;</button> <button class="frac-btn btn-opcion" data-val="=">=</button> <button class="frac-btn btn-opcion" data-val="&gt;">&gt;</button></div>
<!-- Fracción 2 -->
<div id="disp-frac2-crit"></div>
</div>
</div>
<!-- Zona de Comprobación y Retroalimentación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;">
<div id="fb-estado-crit" style="font-weight: bold; font-size: 1.25rem; min-height: 35px; line-height: 1.2; margin-bottom: 5px;"></div>
<!-- Panel teórico que se despliega al acertar -->
<div id="fb-retro-crit" class="retro-panel"></div>
</div>
</div>
<p>
<script>
(function() {
  let ej = { n1: 0, d1: 0, n2: 0, d2: 0, tipo: '' };
  let relacionCorrecta = '';
  let botonesActivos = true;

  function renderFraccion(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function generarNuevoEjercicio() {
    // 50% igual denominador, 50% igual numerador
    ej.tipo = Math.random() > 0.5 ? 'denominador' : 'numerador';

    if (ej.tipo === 'denominador') {
      let dComun = Math.floor(Math.random() * 9) + 2; // entre 2 y 10
      ej.d1 = dComun;
      ej.d2 = dComun;

      // Permitir que a veces sean iguales
      ej.n1 = Math.floor(Math.random() * 10) + 1;
      ej.n2 = Math.floor(Math.random() * 10) + 1;

    } else { // igual numerador
      let nComun = Math.floor(Math.random() * 9) + 1; // entre 1 y 9
      ej.n1 = nComun;
      ej.n2 = nComun;

      ej.d1 = Math.floor(Math.random() * 9) + 2;
      ej.d2 = Math.floor(Math.random() * 9) + 2;
    }

    // Determinar la relación
    let val1 = ej.n1 / ej.d1;
    let val2 = ej.n2 / ej.d2;

    if (val1 < val2) relacionCorrecta = '<';
    else if (val1 > val2) relacionCorrecta = '>';
    else relacionCorrecta = '=';

    // Renderizar
    document.getElementById('disp-frac1-crit').innerHTML = renderFraccion(ej.n1, ej.d1);
    document.getElementById('disp-frac2-crit').innerHTML = renderFraccion(ej.n2, ej.d2);

    // Resetear UI
    let botones = document.querySelectorAll('#botones-crit .btn-opcion');
    botones.forEach(btn => {
      btn.disabled = false;
      btn.style.opacity = '1';
      btn.style.borderColor = '#cbd5e1';
      btn.style.backgroundColor = '#f8fafc';
      btn.style.color = '#0f172a';
    });

    document.getElementById('fb-estado-crit').innerHTML = '';
    document.getElementById('fb-retro-crit').style.display = 'none';
    botonesActivos = true;
  }

  function evaluarRespuesta(e) {
    if (!botonesActivos) return;
    let btnPulsado = e.currentTarget;
    let opcionElegida = btnPulsado.getAttribute('data-val');

    botonesActivos = false;
    let esCorrecto = (opcionElegida === relacionCorrecta);

    // Estilizar botones
    let botones = document.querySelectorAll('#botones-crit .btn-opcion');
    botones.forEach(btn => {
      btn.disabled = true;
      if (btn.getAttribute('data-val') === relacionCorrecta) {
        btn.style.backgroundColor = '#d1fae5';
        btn.style.borderColor = '#10b981';
        btn.style.color = '#065f46';
      } else {
        btn.style.opacity = '0.4';
      }
    });

    if (!esCorrecto) {
      btnPulsado.style.backgroundColor = '#fee2e2';
      btnPulsado.style.borderColor = '#ef4444';
      btnPulsado.style.color = '#991b1b';
      btnPulsado.style.opacity = '1';
    }

    // Preparar el mensaje teórico
    let fbEstado = document.getElementById('fb-estado-crit');
    let fbRetro = document.getElementById('fb-retro-crit');

    let explicacionHTML = '';

    if (ej.tipo === 'denominador') {
      explicacionHTML = `<div style="font-size: 1.05rem; color: #334155;"><strong>💡 Regla (Igual Denominador):</strong> Cuando dos fracciones tienen el mismo denominador (se dividen en las mismas partes), es <strong>MAYOR</strong> la que tiene el <strong>numerador más grande</strong>. En este caso, ${ej.n1} frente a ${ej.n2}.</div>`;
    } else {
      explicacionHTML = `<div style="font-size: 1.05rem; color: #334155;"><strong>💡 Regla (Igual Numerador):</strong> Cuando dos fracciones tienen el mismo numerador (cogemos la misma cantidad de partes), es <strong>MAYOR</strong> la que tiene el <strong>denominador más pequeño</strong> (porque sus porciones son más grandes). En este caso, divisiones entre ${ej.d1} frente a divisiones entre ${ej.d2}.</div>`;
    }

    if (relacionCorrecta === '=') {
        explicacionHTML = `<div style="font-size: 1.05rem; color: #334155;"><strong>💡 Regla (Fracciones Idénticas):</strong> Como tanto el numerador como el denominador son iguales, ambas fracciones representan exactamente la misma cantidad.</div>`;
    }

    if (esCorrecto) {
      fbEstado.innerHTML = `<span style="color: #10b981;">✓ ¡Correcto!</span>`;
      fbRetro.innerHTML = explicacionHTML;
      fbRetro.style.display = 'block';
    } else {
      fbEstado.innerHTML = `<span style="color: #ef4444;">✗ Incorrecto.</span>`;
      fbRetro.innerHTML = explicacionHTML;
      fbRetro.style.display = 'block';
    }
  }

  function inicializarEventos() {
    document.getElementById('btn-nuevo-crit').addEventListener('click', generarNuevoEjercicio);

    let botones = document.querySelectorAll('#botones-crit .btn-opcion');
    botones.forEach(btn => {
      btn.addEventListener('click', evaluarRespuesta);
    });

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
