<div id="frac-bascula" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">La Báscula: Comparación con la Unidad</h3>
<button id="btn-nuevo-bascula" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 20px;">Observa la representación gráfica y compara la fracción con el número 1:</p>
<div style="display: flex; justify-content: center; align-items: center; gap: 20px; flex-wrap: wrap; background: #f8fafc; padding: 25px; border-radius: 12px; border: 2px solid #cbd5e1; box-shadow: 0 4px 6px rgba(0,0,0,0.05); max-width: 800px; margin: 0 auto;"><!-- Fracción izquierda -->
<div id="disp-frac-bascula" style="min-width: 80px;"></div>
<!-- Botones de comparación -->
<div style="display: flex; gap: 10px;" id="botones-comparacion"><button class="frac-btn btn-opcion" data-val="&lt;">&lt;</button> <button class="frac-btn btn-opcion" data-val="=">=</button> <button class="frac-btn btn-opcion" data-val="&gt;">&gt;</button></div>
<!-- La unidad -->
<div style="font-size: 3rem; font-weight: 800; color: #0f172a; min-width: 80px;">1</div>
</div>
<!-- Representación gráfica -->
<div id="svg-container-bascula" style="display: flex; justify-content: center; align-items: center; flex-wrap: wrap; margin-top: 30px; gap: 10px;"><!-- Se inyecta por JS --></div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;">
<div id="fb-mensaje-bascula" style="font-weight: bold; font-size: 1.15rem; min-height: 50px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  let numeradorActual = 0;
  let denominadorActual = 0;
  let relacionCorrecta = '';
  let botonesActivos = true;

  function generarSVGBarra(denominador, porcionesSombreadas) {
    let anchoTotal = 200;
    let alto = 40;
    let anchoPorcion = anchoTotal / denominador;

    let svg = `<svg class="unidad-svg" width="${anchoTotal}" height="${alto}" viewBox="0 0 ${anchoTotal} ${alto}">`;

    for (let i = 0; i < denominador; i++) {
      let x = i * anchoPorcion;
      let rellenar = (i < porcionesSombreadas) ? '#0ea5e9' : '#ffffff';
      svg += `<rect x="${x}" y="0" width="${anchoPorcion}" height="${alto}" fill="${rellenar}" stroke="#334155" stroke-width="2" />`;
    }

    svg += '</svg>';
    return svg;
  }

  function renderFraccion(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function generarNuevoEjercicio() {
    denominadorActual = Math.floor(Math.random() * 8) + 2; // Denominador entre 2 y 9

    // Generar numerador favoreciendo variedad (menor, igual o mayor que 1)
    let tipo = Math.random();
    if (tipo < 0.33) {
      numeradorActual = Math.floor(Math.random() * (denominadorActual - 1)) + 1; // Propias < 1
    } else if (tipo < 0.66) {
      numeradorActual = denominadorActual; // Igual a 1
    } else {
      numeradorActual = denominadorActual + Math.floor(Math.random() * denominadorActual) + 1; // Impropias > 1
    }

    if (numeradorActual < denominadorActual) relacionCorrecta = '<';
    else if (numeradorActual > denominadorActual) relacionCorrecta = '>';
    else relacionCorrecta = '=';

    // UI
    document.getElementById('disp-frac-bascula').innerHTML = renderFraccion(numeradorActual, denominadorActual);

    let numUnidades = Math.ceil(numeradorActual / denominadorActual);
    if (numUnidades === 0) numUnidades = 1; // Para asegurar que siempre dibuje algo (aunque n=0 no debería salir)

    // Dibujar gráficas
    let graficosHTML = '';
    let porcionesRestantes = numeradorActual;

    for (let i = 0; i < numUnidades || i < 1; i++) {
      let sombrearEnEsta = Math.min(porcionesRestantes, denominadorActual);
      graficosHTML += generarSVGBarra(denominadorActual, sombrearEnEsta);
      porcionesRestantes -= sombrearEnEsta;
    }

    document.getElementById('svg-container-bascula').innerHTML = graficosHTML;

    // Resetear botones y feedback
    let botones = document.querySelectorAll('#botones-comparacion .btn-opcion');
    botones.forEach(btn => {
      btn.disabled = false;
      btn.style.opacity = '1';
      btn.style.borderColor = '#cbd5e1';
      btn.style.backgroundColor = '#f8fafc';
      btn.style.color = '#0f172a';
    });

    document.getElementById('fb-mensaje-bascula').innerHTML = '';
    botonesActivos = true;
  }

  function evaluarRespuesta(e) {
    if (!botonesActivos) return;
    let btnPulsado = e.currentTarget;
    let opcionElegida = btnPulsado.getAttribute('data-val');

    botonesActivos = false;
    let esCorrecto = (opcionElegida === relacionCorrecta);

    // Estilizar botones
    let botones = document.querySelectorAll('#botones-comparacion .btn-opcion');
    botones.forEach(btn => {
      btn.disabled = true;
      if (btn.getAttribute('data-val') === relacionCorrecta) {
        btn.style.backgroundColor = '#d1fae5';
        btn.style.borderColor = '#10b981';
        btn.style.color = '#065f46';
      } else {
        btn.style.opacity = '0.4';
      }
    });

    if (!esCorrecto) {
      btnPulsado.style.backgroundColor = '#fee2e2';
      btnPulsado.style.borderColor = '#ef4444';
      btnPulsado.style.color = '#991b1b';
      btnPulsado.style.opacity = '1';
    }

    // Feedback
    let fb = document.getElementById('fb-mensaje-bascula');
    let explicacion = '';

    if (numeradorActual < denominadorActual) {
      explicacion = `El numerador (${numeradorActual}) es MENOR que el denominador (${denominadorActual}). La figura no se llena, por tanto es < 1.`;
    } else if (numeradorActual > denominadorActual) {
      explicacion = `El numerador (${numeradorActual}) es MAYOR que el denominador (${denominadorActual}). Necesitas más de una figura completa, por tanto es > 1.`;
    } else {
      explicacion = `El numerador y el denominador son iguales. La figura se llena exactamente, por tanto es = 1.`;
    }

    if (esCorrecto) {
      fb.innerHTML = `<span style="color: #10b981;">✓ ¡Correcto!</span><br><span style="font-size:1rem; font-weight:600; color:#334155;">${explicacion}</span>`;
    } else {
      fb.innerHTML = `<span style="color: #ef4444;">✗ Incorrecto.</span><br><span style="font-size:1rem; font-weight:600; color:#334155;">${explicacion}</span>`;
    }
  }

  function inicializarEventos() {
    document.getElementById('btn-nuevo-bascula').addEventListener('click', generarNuevoEjercicio);

    let botones = document.querySelectorAll('#botones-comparacion .btn-opcion');
    botones.forEach(btn => {
      btn.addEventListener('click', evaluarRespuesta);
    });

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

