<button id="btn-nuevo-desafio" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 30px;">Compara ambas fracciones y elige el signo adecuado (Mayor, Menor o Igual):</p>
<div style="display: flex; justify-content: center; align-items: center; gap: 30px; flex-wrap: wrap; background: #ffffff; padding: 30px; border-radius: 12px; border: 2px solid #cbd5e1; box-shadow: 0 4px 6px rgba(0,0,0,0.05); max-width: 600px; margin: 0 auto;"><!-- Fracción 1 --> <span class="frac-box" id="frac1-contenedor"> <span class="f-num" id="f1-n"></span> <span class="f-line"></span> <span class="f-den" id="f1-d"></span> </span> <!-- Botones centrales -->
<div style="display: flex; gap: 10px;" id="botones-desafio"><button class="frac-btn btn-opcion" data-val="&lt;">&lt;</button> <button class="frac-btn btn-opcion" data-val="=">=</button> <button class="frac-btn btn-opcion" data-val="&gt;">&gt;</button></div>
<!-- Fracción 2 --> <span class="frac-box" id="frac2-contenedor"> <span class="f-num" id="f2-n"></span> <span class="f-line"></span> <span class="f-den" id="f2-d"></span> </span></div>
</div>
<!-- Zona de Comprobación y Demostración -->
<div style="text-align: center; margin-top: 20px;">
<div id="fb-estado-desafio" style="font-weight: 800; font-size: 1.3rem; margin-bottom: 10px; min-height: 35px;"></div>
<!-- Panel de demostración de productos cruzados -->
<div id="panel-demostracion" class="panel-demostracion">
<div style="font-weight: bold; color: #0f172a; margin-bottom: 15px; font-size: 1.1rem;">Comprobación por productos cruzados:</div>
<div style="display: flex; justify-content: space-around; flex-wrap: wrap; gap: 20px;"><!-- Cruce Izquierdo -->
<div style="background: #ffffff; border: 2px solid #8b5cf6; border-radius: 8px; padding: 15px; flex: 1; min-width: 200px;">
<div style="font-size: 0.95rem; color: #475569; margin-bottom: 5px;">Numerador 1 × Denominador 2</div>
<div style="font-size: 1.4rem; font-weight: bold; color: #7c3aed;"><span id="demo-n1"></span> × <span id="demo-d2"></span> = <span id="demo-res1"></span></div>
</div>
<!-- Símbolo resultante central -->
<div style="display: flex; align-items: center; justify-content: center;">
<div id="demo-simbolo" style="font-size: 2.5rem; font-weight: 900; color: #0f172a; background: #e2e8f0; width: 60px; height: 60px; border-radius: 50%; display: flex; align-items: center; justify-content: center;"></div>
</div>
<!-- Cruce Derecho -->
<div style="background: #ffffff; border: 2px solid #f59e0b; border-radius: 8px; padding: 15px; flex: 1; min-width: 200px;">
<div style="font-size: 0.95rem; color: #475569; margin-bottom: 5px;">Numerador 2 × Denominador 1</div>
<div style="font-size: 1.4rem; font-weight: bold; color: #d97706;"><span id="demo-n2"></span> × <span id="demo-d1"></span> = <span id="demo-res2"></span></div>
</div>
</div>
</div>
</div>
</div>
<p>
<script>
(function() {
  let ej = { n1: 0, d1: 0, n2: 0, d2: 0 };
  let prod1 = 0;
  let prod2 = 0;
  let relacionCorrecta = '';
  let botonesActivos = true;

  function generarNuevoEjercicio() {
    // Generar fracciones aleatorias (fomentando a veces igualdades para dar variedad)
    ej.d1 = Math.floor(Math.random() * 9) + 2; 
    ej.d2 = Math.floor(Math.random() * 9) + 2;
    ej.n1 = Math.floor(Math.random() * 10) + 1;
    ej.n2 = Math.floor(Math.random() * 10) + 1;

    // Posibilidad de forzar fracciones equivalentes (15% probabilidad)
    if (Math.random() < 0.15) {
      let factor = Math.floor(Math.random() * 3) + 2;
      ej.n2 = ej.n1 * factor;
      ej.d2 = ej.d1 * factor;
      // Mezclar izquierda o derecha
      if (Math.random() > 0.5) {
        let tempN = ej.n1; let tempD = ej.d1;
        ej.n1 = ej.n2; ej.d1 = ej.d2;
        ej.n2 = tempN; ej.d2 = tempD;
      }
    }

    prod1 = ej.n1 * ej.d2;
    prod2 = ej.n2 * ej.d1;

    if (prod1 < prod2) relacionCorrecta = '<';
    else if (prod1 > prod2) relacionCorrecta = '>';
    else relacionCorrecta = '=';

    // Pintar UI
    document.getElementById('f1-n').textContent = ej.n1;
    document.getElementById('f1-n').style.color = '#0f172a';
    document.getElementById('f1-d').textContent = ej.d1;
    document.getElementById('f1-d').style.color = '#0f172a';

    document.getElementById('f2-n').textContent = ej.n2;
    document.getElementById('f2-n').style.color = '#0f172a';
    document.getElementById('f2-d').textContent = ej.d2;
    document.getElementById('f2-d').style.color = '#0f172a';

    // Resetear botones
    let botones = document.querySelectorAll('#botones-desafio .btn-opcion');
    botones.forEach(btn => {
      btn.disabled = false;
      btn.style.opacity = '1';
      btn.style.borderColor = '#cbd5e1';
      btn.style.backgroundColor = '#f8fafc';
      btn.style.color = '#0f172a';
    });

    document.getElementById('fb-estado-desafio').innerHTML = '';
    document.getElementById('panel-demostracion').style.display = 'none';
    botonesActivos = true;
  }

  function evaluarRespuesta(e) {
    if (!botonesActivos) return;
    let btnPulsado = e.currentTarget;
    let opcionElegida = btnPulsado.getAttribute('data-val');

    botonesActivos = false;
    let esCorrecto = (opcionElegida === relacionCorrecta);

    // Colorear números temporalmente para indicar los productos cruzados
    document.getElementById('f1-n').style.color = '#8b5cf6'; // Morado
    document.getElementById('f2-d').style.color = '#8b5cf6';

    document.getElementById('f2-n').style.color = '#f59e0b'; // Naranja
    document.getElementById('f1-d').style.color = '#f59e0b';

    // Estilizar botones centrales
    let botones = document.querySelectorAll('#botones-desafio .btn-opcion');
    botones.forEach(btn => {
      btn.disabled = true;
      if (btn.getAttribute('data-val') === relacionCorrecta) {
        btn.style.backgroundColor = '#d1fae5';
        btn.style.borderColor = '#10b981';
        btn.style.color = '#065f46';
      } else {
        btn.style.opacity = '0.3';
      }
    });

    if (!esCorrecto) {
      btnPulsado.style.backgroundColor = '#fee2e2';
      btnPulsado.style.borderColor = '#ef4444';
      btnPulsado.style.color = '#991b1b';
      btnPulsado.style.opacity = '1';
    }

    // Mostrar feedback
    let fbEstado = document.getElementById('fb-estado-desafio');
    if (esCorrecto) {
      fbEstado.innerHTML = `<span style="color: #10b981;">✓ ¡Correcto!</span>`;
    } else {
      fbEstado.innerHTML = `<span style="color: #ef4444;">✗ Incorrecto. Fíjate en la comprobación.</span>`;
    }

    // Configurar panel de demostración
    document.getElementById('demo-n1').textContent = ej.n1;
    document.getElementById('demo-d2').textContent = ej.d2;
    document.getElementById('demo-res1').textContent = prod1;

    document.getElementById('demo-n2').textContent = ej.n2;
    document.getElementById('demo-d1').textContent = ej.d1;
    document.getElementById('demo-res2').textContent = prod2;

    let simColor = '';
    if (relacionCorrecta === '<') simColor = '#3b82f6';
    else if (relacionCorrecta === '>') simColor = '#ef4444';
    else simColor = '#10b981';

    let simEl = document.getElementById('demo-simbolo');
    simEl.textContent = relacionCorrecta;
    simEl.style.color = simColor;
    simEl.style.border = `2px solid ${simColor}`;
    simEl.style.background = '#ffffff';

    document.getElementById('panel-demostracion').style.display = 'block';
  }

  function inicializarEventos() {
    document.getElementById('btn-nuevo-desafio').addEventListener('click', generarNuevoEjercicio);

    let botones = document.querySelectorAll('#botones-desafio .btn-opcion');
    botones.forEach(btn => {
      btn.addEventListener('click', evaluarRespuesta);
    });

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

