<div id="frac-suma-igual" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">Sumador Visual (Igual Denominador)</h3>
<button id="btn-nueva-suma" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p id="instruccion-suma" style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 20px;">Paso 1: Colorea las fracciones iniciales para representar la suma.</p>
<div style="display: flex; justify-content: center; align-items: stretch; gap: 15px; flex-wrap: wrap; margin: 0 auto;"><!-- Fracción 1 -->
<div class="frac-container" id="cont-frac1">
<div id="disp-frac1-suma"></div>
<div id="svg-frac1-suma" style="display: flex; justify-content: center; align-items: center; flex-wrap: wrap; gap: 5px;"></div>
</div>
<!-- Operador Suma -->
<div class="operador">+</div>
<!-- Fracción 2 -->
<div class="frac-container" id="cont-frac2">
<div id="disp-frac2-suma"></div>
<div id="svg-frac2-suma" style="display: flex; justify-content: center; align-items: center; flex-wrap: wrap; gap: 5px;"></div>
</div>
<!-- Operador Igual -->
<div class="operador" id="op-igual" style="opacity: 0.3; transition: opacity 0.3s;">=</div>
<!-- Resultado (Inicialmente bloqueado visualmente) -->
<div class="frac-container" id="cont-frac-res" style="opacity: 0.3; transition: opacity 0.3s; background: #e2e8f0;"><span class="frac-box" style="padding-top: 10px;"> <input type="number" id="inp-num-res" class="f-input" placeholder="?" disabled="disabled" /> <span class="f-line" style="background: #64748b;"></span> <input type="number" id="inp-den-res" class="f-input" placeholder="?" disabled="disabled" /> </span>
<div id="svg-frac-res" style="display: flex; justify-content: center; align-items: center; flex-wrap: wrap; gap: 5px; min-height: 100px;"></div>
</div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-suma" class="frac-btn frac-btn-check">Comprobar Coloreado</button>
<div id="fb-mensaje-suma" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 50px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  let ej = { d: 0, n1: 0, n2: 0, nRes: 0 };
  let coloreadas1 = 0;
  let coloreadas2 = 0;
  let fase = 1; // 1: colorear sumandos, 2: calcular resultado

  function renderFraccionEstatica(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function generarSVGBarraInteractiva(denominador, idGrupo, baseId) {
    let anchoTotal = 150;
    let alto = 35;
    let anchoPorcion = anchoTotal / denominador;

    let svg = `<svg class="svg-shape" width="${anchoTotal}" height="${alto}" viewBox="0 0 ${anchoTotal} ${alto}" style="display:block; margin: 3px;">`;

    for (let i = 0; i < denominador; i++) {
      let x = i * anchoPorcion;
      svg += `<rect x="${x}" y="0" width="${anchoPorcion}" height="${alto}" fill="#ffffff" stroke="#334155" stroke-width="2" class="slice" data-selected="false" data-grupo="${idGrupo}" style="cursor:pointer; transition: fill 0.2s;" />`;
    }

    svg += '</svg>';
    return svg;
  }

  function generarSVGBarraResultado(denominador, porcionesLlenas) {
    let anchoTotal = 150;
    let alto = 35;
    let anchoPorcion = anchoTotal / denominador;
    let svg = `<svg class="svg-shape" width="${anchoTotal}" height="${alto}" viewBox="0 0 ${anchoTotal} ${alto}" style="display:block; margin: 3px;">`;

    for (let i = 0; i < denominador; i++) {
      let x = i * anchoPorcion;
      let color = (i < porcionesLlenas) ? '#10b981' : '#ffffff'; // Verde para el resultado
      svg += `<rect x="${x}" y="0" width="${anchoPorcion}" height="${alto}" fill="${color}" stroke="#334155" stroke-width="2" />`;
    }
    svg += '</svg>';
    return svg;
  }

  function generarNuevoEjercicio() {
    fase = 1;
    ej.d = Math.floor(Math.random() * 8) + 2; // Denominadores de 2 a 9

    // Generar numeradores. Permitir que la suma supere la unidad (impropias) para más variedad.
    ej.n1 = Math.floor(Math.random() * ej.d) + 1;
    ej.n2 = Math.floor(Math.random() * ej.d) + 1;
    ej.nRes = ej.n1 + ej.n2;

    coloreadas1 = 0;
    coloreadas2 = 0;

    // Renderizar fracciones numéricas
    document.getElementById('disp-frac1-suma').innerHTML = renderFraccionEstatica(ej.n1, ej.d);
    document.getElementById('disp-frac2-suma').innerHTML = renderFraccionEstatica(ej.n2, ej.d);

    // Calcular figuras necesarias
    let fig1 = Math.ceil(ej.n1 / ej.d); if(fig1===0) fig1=1;
    let fig2 = Math.ceil(ej.n2 / ej.d); if(fig2===0) fig2=1;

    let htmlFig1 = ''; for(let i=0; i<fig1; i++) htmlFig1 += generarSVGBarraInteractiva(ej.d, 1);
    let htmlFig2 = ''; for(let i=0; i<fig2; i++) htmlFig2 += generarSVGBarraInteractiva(ej.d, 2);

    document.getElementById('svg-frac1-suma').innerHTML = htmlFig1;
    document.getElementById('svg-frac2-suma').innerHTML = htmlFig2;

    // Resetear UI del resultado
    document.getElementById('svg-frac-res').innerHTML = '';
    document.getElementById('cont-frac-res').style.opacity = '0.3';
    document.getElementById('cont-frac-res').style.background = '#e2e8f0';
    document.getElementById('op-igual').style.opacity = '0.3';

    let inpN = document.getElementById('inp-num-res');
    let inpD = document.getElementById('inp-den-res');
    inpN.value = ''; inpD.value = '';
    inpN.disabled = true; inpD.disabled = true;
    inpN.style.background = '#f8fafc'; inpD.style.background = '#f8fafc';
    inpN.style.borderColor = '#94a3b8'; inpD.style.borderColor = '#94a3b8';
    inpN.style.color = '#0284c7'; inpD.style.color = '#0284c7';

    // Instrucciones y botón
    document.getElementById('instruccion-suma').textContent = "Paso 1: Colorea las fracciones iniciales para representar la suma.";
    let btn = document.getElementById('btn-comprobar-suma');
    btn.textContent = "Comprobar Coloreado";
    btn.disabled = false;
    btn.style.opacity = '1';

    document.getElementById('fb-mensaje-suma').innerHTML = '';
  }

  function interactuarPorcion(e) {
    if (fase !== 1) return; // Bloquear clicks en fase 2
    let target = e.target;
    if (target && target.getAttribute('data-selected') !== null) {
      let isSelected = target.getAttribute('data-selected') === 'true';
      let idGrupo = parseInt(target.getAttribute('data-grupo'));

      if (!isSelected) {
        target.setAttribute('fill', '#0ea5e9'); 
        target.setAttribute('data-selected', 'true');
        if (idGrupo === 1) coloreadas1++;
        if (idGrupo === 2) coloreadas2++;
      } else {
        target.setAttribute('fill', '#ffffff'); 
        target.setAttribute('data-selected', 'false');
        if (idGrupo === 1) coloreadas1--;
        if (idGrupo === 2) coloreadas2--;
      }
    }
  }

  function comprobarPaso1() {
    let fb = document.getElementById('fb-mensaje-suma');
    let ok1 = (coloreadas1 === ej.n1);
    let ok2 = (coloreadas2 === ej.n2);

    if (ok1 && ok2) {
      fase = 2; // Avanzar
      fb.style.color = '#10b981';
      fb.innerHTML = '✓ ¡Perfecto! Fíjate en cómo las porciones se trasladan al resultado.';

      // Bloquear gráficos originales
      document.querySelectorAll('#svg-frac1-suma .slice, #svg-frac2-suma .slice').forEach(el => el.style.cursor = 'default');

      // Animación: Activar zona de resultado y dibujar gráficos
      document.getElementById('op-igual').style.opacity = '1';
      let contRes = document.getElementById('cont-frac-res');
      contRes.style.opacity = '1';
      contRes.style.background = '#f8fafc';

      let figRes = Math.ceil(ej.nRes / ej.d); if(figRes===0) figRes=1;
      let htmlRes = '';
      let porcionesRestantes = ej.nRes;
      for(let i=0; i<figRes; i++) {
         let llenar = Math.min(porcionesRestantes, ej.d);
         htmlRes += generarSVGBarraResultado(ej.d, llenar);
         porcionesRestantes -= llenar;
      }
      document.getElementById('svg-frac-res').innerHTML = htmlRes;

      // Activar inputs
      let inpN = document.getElementById('inp-num-res');
      let inpD = document.getElementById('inp-den-res');
      inpN.disabled = false; inpD.disabled = false;
      inpN.style.background = '#ffffff'; inpD.style.background = '#ffffff';

      // Actualizar instrucciones y botón
      document.getElementById('instruccion-suma').innerHTML = "Paso 2: Observa la figura final y escribe la fracción suma. <br><span style='font-size:0.95rem; color:#64748b;'>(No hace falta simplificar)</span>";
      let btn = document.getElementById('btn-comprobar-suma');
      btn.textContent = "Comprobar Suma";

      inpN.focus();

    } else {
      fb.style.color = '#ef4444';
      let msg = '✗ Revisa el coloreado.<br><span style="font-size:1rem; font-weight:600;">';
      if (!ok1) msg += `En la primera fracción llevas ${coloreadas1} de ${ej.n1}.<br>`;
      if (!ok2) msg += `En la segunda fracción llevas ${coloreadas2} de ${ej.n2}.`;
      msg += '</span>';
      fb.innerHTML = msg;
    }
  }

  function comprobarPaso2() {
    let inpN = document.getElementById('inp-num-res');
    let inpD = document.getElementById('inp-den-res');
    let valN = parseInt(inpN.value);
    let valD = parseInt(inpD.value);
    let fb = document.getElementById('fb-mensaje-suma');

    if (isNaN(valN) || isNaN(valD)) {
      fb.style.color = '#ef4444';
      fb.innerHTML = '✗ Faltan números por rellenar.';
      return;
    }

    // Permitimos la fracción original de la suma, y también equivalentes correctas (si la simplificó)
    // Para simplificar la validación didáctica del gráfico, pediremos estrictamente n1+n2 / d
    if (valN === ej.nRes && valD === ej.d) {
      fb.style.color = '#10b981';
      fb.innerHTML = `✓ ¡Correcto! Al sumar fracciones con igual denominador, se suman los numeradores (${ej.n1} + ${ej.n2}) y se mantiene el denominador (${ej.d}).`;
      document.getElementById('btn-comprobar-suma').disabled = true;
      document.getElementById('btn-comprobar-suma').style.opacity = '0.5';

      inpN.disabled = true; inpD.disabled = true;
      inpN.style.background = '#d1fae5'; inpD.style.background = '#d1fae5';
      inpN.style.borderColor = '#10b981'; inpD.style.borderColor = '#10b981';
      inpN.style.color = '#065f46'; inpD.style.color = '#065f46';
    } else {
      fb.style.color = '#ef4444';
      let msg = '✗ Incorrecto.<br><span style="font-size:1rem; font-weight:600;">';
      if (valD !== ej.d) msg += `Recuerda: El denominador NO se suma, se mantiene igual porque el tamaño de la porción es el mismo.<br>`;
      if (valN !== ej.nRes) msg += `Cuenta bien las porciones verdes totales del resultado.`;
      msg += '</span>';
      fb.innerHTML = msg;
    }
  }

  function manejadorBotonComprobar() {
    if (fase === 1) comprobarPaso1();
    else if (fase === 2) comprobarPaso2();
  }

  function inicializarEventos() {
    document.getElementById('btn-nueva-suma').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-suma').addEventListener('click', manejadorBotonComprobar);

    document.getElementById('svg-frac1-suma').addEventListener('click', interactuarPorcion);
    document.getElementById('svg-frac2-suma').addEventListener('click', interactuarPorcion);

    // Soporte Enter en el input inferior
    document.getElementById('inp-den-res').addEventListener('keypress', function(e) {
      if (e.key === 'Enter' && fase === 2) comprobarPaso2();
    });

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
