<div id="frac-suma-distinto" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">Laboratorio de Sumas (Distinto Denominador)</h3>
<button id="btn-nueva-sumad" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px; max-width: 700px; margin: 0 auto;"><!-- Enunciado Principal -->
<div style="display: flex; justify-content: center; align-items: center; gap: 10px; margin-bottom: 25px; background: #ffffff; padding: 15px; border-radius: 12px; border: 2px dashed #94a3b8;"><span class="operador" style="font-size: 1.5rem; color: #475569;">Suma:</span>
<div id="disp-sumandos" style="display: flex; align-items: center; gap: 10px;"></div>
</div>
<!-- PASO 1: Calcular mcm -->
<div class="paso-panel" id="panel-paso1">
<div class="paso-titulo">Paso 1: Mínimo Común Múltiplo</div>
<div style="font-size: 1.3rem; font-weight: bold; color: #0f172a;">m.c.m. ( <span id="txt-d1"></span> , <span id="txt-d2"></span> ) = <input type="number" id="inp-mcm" class="f-input" style="width: 80px !important; margin-left: 10px !important;" placeholder="?" /></div>
</div>
<!-- PASO 2: Amplificar (Bloqueado inicialmente) -->
<div class="paso-panel" id="panel-paso2" style="opacity: 0.3; pointer-events: none;">
<div class="paso-titulo">Paso 2: Fracciones Equivalentes</div>
<div style="display: flex; justify-content: center; align-items: center; gap: 10px;"><span class="frac-box"> <input type="number" id="inp-eq-n1" class="f-input" placeholder="?" /> <span class="f-line"></span> <span class="f-den" id="txt-mcm1" style="color: #10b981;"></span> </span> <span class="operador">+</span> <span class="frac-box"> <input type="number" id="inp-eq-n2" class="f-input" placeholder="?" /> <span class="f-line"></span> <span class="f-den" id="txt-mcm2" style="color: #10b981;"></span> </span></div>
</div>
<!-- PASO 3: Suma Final (Bloqueado inicialmente) -->
<div class="paso-panel" id="panel-paso3" style="opacity: 0.3; pointer-events: none; border-color: #10b981; background: #f0fdf4;">
<div class="paso-titulo" style="color: #065f46; border-color: #a7f3d0;">Paso 3: Suma Final (Numeradores)</div>
<div style="display: flex; justify-content: center; align-items: center; gap: 10px;"><span class="frac-box"> <input type="number" id="inp-res-n" class="f-input" placeholder="?" /> <span class="f-line" style="background: #059669;"></span> <span class="f-den" id="txt-mcm-res" style="color: #059669;"></span> </span></div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-sumad" class="frac-btn frac-btn-check">Comprobar m.c.m.</button>
<div id="fb-mensaje-sumad" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 50px; line-height: 1.4;"></div>
</div>
