<p>
<script>
(function() {
  // Base de datos de ejercicios extraída del cuaderno
  const ejerciciosD = [
    {n1: 2, d1: 3, n2: 4, d2: 9},
    {n1: 6, d1: 7, n2: 8, d2: 1},
    {n1: 3, d1: 8, n2: 5, d2: 5},
    {n1: 7, d1: 6, n2: 9, d2: 4},
    {n1: 1, d1: 2, n2: 6, d2: 8},
    {n1: 9, d1: 4, n2: 2, d2: 7},
    {n1: 5, d1: 5, n2: 9, d2: 2},
    {n1: 9, d1: 1, n2: 4, d2: 3},
    {n1: 7, d1: 9, n2: 1, d2: 8},
    {n1: 8, d1: 2, n2: 4, d2: 3}
  ];

  let ej = {};
  let fase = 1;

  function calcularMCD(a, b) { return b === 0 ? a : calcularMCD(b, a % b); }
  function calcularMCM(a, b) { return (a * b) / calcularMCD(a, b); }

  function renderFraccion(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function generarNuevoEjercicio() {
    fase = 1;
    let base = ejerciciosD[Math.floor(Math.random() * ejerciciosD.length)];

    // Aleatorizar orden
    if (Math.random() > 0.5) {
      ej = { n1: base.n2, d1: base.d2, n2: base.n1, d2: base.d1 };
    } else {
      ej = { n1: base.n1, d1: base.d1, n2: base.n2, d2: base.d2 };
    }

    ej.targetMcm = calcularMCM(ej.d1, ej.d2);
    ej.targetEqN1 = ej.n1 * (ej.targetMcm / ej.d1);
    ej.targetEqN2 = ej.n2 * (ej.targetMcm / ej.d2);
    ej.targetResN = ej.targetEqN1 + ej.targetEqN2;

    // UI Principal
    document.getElementById('disp-sumandos').innerHTML = renderFraccion(ej.n1, ej.d1) + '<span class="operador">+</span>' + renderFraccion(ej.n2, ej.d2);
    document.getElementById('txt-d1').textContent = ej.d1;
    document.getElementById('txt-d2').textContent = ej.d2;

    // Resetear Paneles
    document.getElementById('panel-paso1').style.opacity = '1';
    document.getElementById('panel-paso1').style.pointerEvents = 'auto';

    document.getElementById('panel-paso2').style.opacity = '0.3';
    document.getElementById('panel-paso2').style.pointerEvents = 'none';

    document.getElementById('panel-paso3').style.opacity = '0.3';
    document.getElementById('panel-paso3').style.pointerEvents = 'none';

    // Resetear Inputs
    ['inp-mcm', 'inp-eq-n1', 'inp-eq-n2', 'inp-res-n'].forEach(id => {
      let el = document.getElementById(id);
      el.value = '';
      el.disabled = false;
      el.style.background = '#f8fafc';
      el.style.borderColor = '#94a3b8';
      el.style.color = '#0284c7';
    });

    // Etiquetas fijas
    document.getElementById('txt-mcm1').textContent = '?';
    document.getElementById('txt-mcm2').textContent = '?';
    document.getElementById('txt-mcm-res').textContent = '?';

    // Botón y Feedback
    let btn = document.getElementById('btn-comprobar-sumad');
    btn.textContent = "Comprobar m.c.m.";
    btn.disabled = false;
    btn.style.opacity = '1';

    document.getElementById('fb-mensaje-sumad').innerHTML = '';
    document.getElementById('inp-mcm').focus();
  }

  function comprobarPaso1() {
    let inp = document.getElementById('inp-mcm');
    let val = parseInt(inp.value);
    let fb = document.getElementById('fb-mensaje-sumad');

    if (isNaN(val)) { fb.style.color = '#ef4444'; fb.innerHTML = '✗ Escribe el m.c.m.'; return; }

    if (val === ej.targetMcm) {
      fase = 2;
      fb.style.color = '#10b981';
      fb.innerHTML = `✓ ¡Bien! El m.c.m. de ${ej.d1} y ${ej.d2} es ${ej.targetMcm}. Ahora encuentra los nuevos numeradores.`;

      inp.disabled = true;
      inp.style.background = '#d1fae5';
      inp.style.borderColor = '#10b981';
      inp.style.color = '#065f46';

      // Desbloquear Paso 2
      document.getElementById('panel-paso2').style.opacity = '1';
      document.getElementById('panel-paso2').style.pointerEvents = 'auto';
      document.getElementById('txt-mcm1').textContent = ej.targetMcm;
      document.getElementById('txt-mcm2').textContent = ej.targetMcm;

      let btn = document.getElementById('btn-comprobar-sumad');
      btn.textContent = "Comprobar Equivalentes";
      document.getElementById('inp-eq-n1').focus();

    } else {
      fb.style.color = '#ef4444';
      fb.innerHTML = `✗ Incorrecto. Revisa la factorización de ${ej.d1} y ${ej.d2} para hallar el m.c.m.`;
    }
  }

  function comprobarPaso2() {
    let in1 = document.getElementById('inp-eq-n1');
    let in2 = document.getElementById('inp-eq-n2');
    let v1 = parseInt(in1.value);
    let v2 = parseInt(in2.value);
    let fb = document.getElementById('fb-mensaje-sumad');

    if (isNaN(v1) || isNaN(v2)) { fb.style.color = '#ef4444'; fb.innerHTML = '✗ Faltan numeradores por rellenar.'; return; }

    let ok1 = (v1 === ej.targetEqN1);
    let ok2 = (v2 === ej.targetEqN2);

    if (ok1 && ok2) {
      fase = 3;
      fb.style.color = '#10b981';
      fb.innerHTML = `✓ ¡Excelente! Has amplificado correctamente. Ya tienes el mismo denominador, procede a sumar.`;

      in1.disabled = true; in2.disabled = true;
      in1.style.background = '#d1fae5'; in2.style.background = '#d1fae5';
      in1.style.borderColor = '#10b981'; in2.style.borderColor = '#10b981';
      in1.style.color = '#065f46'; in2.style.color = '#065f46';

      // Desbloquear Paso 3
      document.getElementById('panel-paso3').style.opacity = '1';
      document.getElementById('panel-paso3').style.pointerEvents = 'auto';
      document.getElementById('txt-mcm-res').textContent = ej.targetMcm;

      let btn = document.getElementById('btn-comprobar-sumad');
      btn.textContent = "Comprobar Suma Final";
      document.getElementById('inp-res-n').focus();

    } else {
      fb.style.color = '#ef4444';
      let msg = '✗ Hay errores.<br><span style="font-size:1rem; font-weight:600;">';
      if (!ok1) msg += `Fracción 1: Divide ${ej.targetMcm} entre ${ej.d1} y multiplica por ${ej.n1}.<br>`;
      if (!ok2) msg += `Fracción 2: Divide ${ej.targetMcm} entre ${ej.d2} y multiplica por ${ej.n2}.`;
      msg += '</span>';
      fb.innerHTML = msg;
    }
  }

  function comprobarPaso3() {
    let inp = document.getElementById('inp-res-n');
    let val = parseInt(inp.value);
    let fb = document.getElementById('fb-mensaje-sumad');

    if (isNaN(val)) { fb.style.color = '#ef4444'; fb.innerHTML = '✗ Escribe el numerador final.'; return; }

    if (val === ej.targetResN) {
      fb.style.color = '#10b981';
      fb.innerHTML = `✓ ¡Enhorabuena! Has completado todo el proceso de suma con distinto denominador con éxito.`;

      inp.disabled = true;
      inp.style.background = '#d1fae5';
      inp.style.borderColor = '#10b981';
      inp.style.color = '#065f46';

      let btn = document.getElementById('btn-comprobar-sumad');
      btn.disabled = true;
      btn.style.opacity = '0.5';
    } else {
      fb.style.color = '#ef4444';
      fb.innerHTML = `✗ Incorrecto. Solo tienes que sumar los numeradores equivalentes que calculaste en el paso 2.`;
    }
  }

  function manejadorBotonComprobar() {
    if (fase === 1) comprobarPaso1();
    else if (fase === 2) comprobarPaso2();
    else if (fase === 3) comprobarPaso3();
  }

  function inicializarEventos() {
    document.getElementById('btn-nueva-sumad').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-sumad').addEventListener('click', manejadorBotonComprobar);

    // Soporte Enter para inputs de cada fase
    document.getElementById('inp-mcm').addEventListener('keypress', e => { if (e.key === 'Enter' && fase === 1) comprobarPaso1(); });
    document.getElementById('inp-eq-n2').addEventListener('keypress', e => { if (e.key === 'Enter' && fase === 2) comprobarPaso2(); });
    document.getElementById('inp-res-n').addEventListener('keypress', e => { if (e.key === 'Enter' && fase === 3) comprobarPaso3(); });

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

