<div id="frac-resta-igual" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">Restador Gráfico (Igual Denominador)</h3>
<button id="btn-nueva-resta" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p id="instruccion-resta" style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 20px;">Paso 1: Haz clic en las porciones para <strong>restar o quitar</strong> la cantidad de la segunda fracción.</p>
<div style="display: flex; justify-content: center; align-items: stretch; gap: 15px; flex-wrap: wrap; margin: 0 auto;"><!-- Operación Original Numérica -->
<div style="display: flex; align-items: center; gap: 10px; margin-bottom: 10px; width: 100%; justify-content: center;">
<div id="disp-frac1-resta"></div>
<div class="operador" style="font-size: 2.5rem;">-</div>
<div id="disp-frac2-resta"></div>
</div>
<!-- Fracción 1 (Gráfico interactivo) -->
<div class="frac-container" id="cont-frac1" style="width: 100%; max-width: 400px; padding: 30px;">
<div id="svg-frac1-resta" style="display: flex; justify-content: center; align-items: center; flex-wrap: wrap; gap: 5px;"></div>
</div>
<!-- Operador Igual -->
<div class="operador" id="op-igual" style="opacity: 0.3; transition: opacity 0.3s; flex-direction: column; justify-content: center;">=</div>
<!-- Resultado (Inicialmente bloqueado) -->
<div class="frac-container" id="cont-frac-res" style="opacity: 0.3; transition: opacity 0.3s; background: #e2e8f0; justify-content: center;"><span class="frac-box" style="padding: 10px 20px;"> <input type="number" id="inp-num-res" class="f-input" placeholder="?" disabled="disabled" /> <span class="f-line" style="background: #64748b;"></span> <input type="number" id="inp-den-res" class="f-input" placeholder="?" disabled="disabled" /> </span></div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-resta" class="frac-btn frac-btn-check">Comprobar Resta</button>
<div id="fb-mensaje-resta" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 50px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  let ej = { d: 0, n1: 0, n2: 0, nRes: 0 };
  let porcionesBorradas = 0;
  let fase = 1;

  function renderFraccionEstatica(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function generarGraficoCircularSVG(denominador, porcionesLlenas) {
    let svg = `<svg width="180" height="180" viewBox="-90 -90 180 180" style="transform: rotate(-90deg); overflow: visible; drop-shadow: 0 4px 6px rgba(0,0,0,0.1); margin: 10px;">`;

    if (denominador === 1) {
      // Caso 1/1 (entero completo), aunque no suele salir en el random actual
      let color = (porcionesLlenas > 0) ? '#0ea5e9' : '#ffffff';
      svg += `<circle cx="0" cy="0" r="80" fill="${color}" stroke="#334155" stroke-width="2.5" class="slice" data-selected="true" style="cursor:pointer; transition: fill 0.2s;"></circle>`;
    } else {
      let angulo = (2 * Math.PI) / denominador;
      for (let i = 0; i < denominador; i++) {
        let a1 = i * angulo;
        let a2 = (i + 1) * angulo;
        let x1 = 80 * Math.cos(a1);
        let y1 = 80 * Math.sin(a1);
        let x2 = 80 * Math.cos(a2);
        let y2 = 80 * Math.sin(a2);

        let largeArc = (a2 - a1) > Math.PI ? 1 : 0;
        let pathData = `M 0 0 L ${x1} ${y1} A 80 80 0 ${largeArc} 1 ${x2} ${y2} Z`;

        let isSelected = (i < porcionesLlenas);
        let color = isSelected ? '#0ea5e9' : '#ffffff';

        // Solo las porciones coloreadas inicialmente son clicables para "restar"
        let cursorStyle = isSelected ? 'cursor:pointer;' : 'cursor:default;';

        svg += `<path d="${pathData}" fill="${color}" stroke="#334155" stroke-width="2.5" class="slice" data-original-selected="${isSelected}" data-selected="${isSelected}" style="${cursorStyle} transition: fill 0.2s;"></path>`;
      }
    }
    svg += '</svg>';
    return svg;
  }

  function generarNuevoEjercicio() {
    fase = 1;
    ej.d = Math.floor(Math.random() * 7) + 3; // Denominadores de 3 a 9 (mejor para gráficos circulares)

    // Aseguramos n1 > n2 para que la resta sea positiva y dentro de la unidad
    ej.n1 = Math.floor(Math.random() * (ej.d - 1)) + 2; 
    ej.n2 = Math.floor(Math.random() * (ej.n1 - 1)) + 1;
    ej.nRes = ej.n1 - ej.n2;

    porcionesBorradas = 0;

    // Renderizar fracciones numéricas
    document.getElementById('disp-frac1-resta').innerHTML = renderFraccionEstatica(ej.n1, ej.d);
    document.getElementById('disp-frac2-resta').innerHTML = renderFraccionEstatica(ej.n2, ej.d);

    // Dibujar el gráfico circular de la primera fracción (n1/d)
    document.getElementById('svg-frac1-resta').innerHTML = generarGraficoCircularSVG(ej.d, ej.n1);

    // Resetear UI del resultado
    document.getElementById('cont-frac-res').style.opacity = '0.3';
    document.getElementById('cont-frac-res').style.background = '#e2e8f0';
    document.getElementById('op-igual').style.opacity = '0.3';

    let inpN = document.getElementById('inp-num-res');
    let inpD = document.getElementById('inp-den-res');
    inpN.value = ''; inpD.value = '';
    inpN.disabled = true; inpD.disabled = true;
    inpN.style.background = '#f8fafc'; inpD.style.background = '#f8fafc';
    inpN.style.borderColor = '#94a3b8'; inpD.style.borderColor = '#94a3b8';
    inpN.style.color = '#0284c7'; inpD.style.color = '#0284c7';

    // Instrucciones y botón
    document.getElementById('instruccion-resta').innerHTML = `Paso 1: Haz clic en las porciones para <strong>restar o borrar</strong> exactamente ${ej.n2} ${ej.n2===1?'parte':'partes'} de la figura.`;
    let btn = document.getElementById('btn-comprobar-resta');
    btn.textContent = "Comprobar Resta Gráfica";
    btn.disabled = false;
    btn.style.opacity = '1';

    document.getElementById('fb-mensaje-resta').innerHTML = '';
  }

  function interactuarPorcion(e) {
    if (fase !== 1) return; // Bloquear clicks en fase 2
    let target = e.target;

    // Solo podemos interactuar con las porciones que originalmente estaban coloreadas
    if (target && target.getAttribute('data-original-selected') === 'true') {
      let isSelected = target.getAttribute('data-selected') === 'true';

      if (isSelected) {
        // Borramos o "restamos" la porción (la pintamos de blanco o un gris muy claro)
        target.setAttribute('fill', '#f1f5f9'); 
        target.setAttribute('data-selected', 'false');
        porcionesBorradas++;
      } else {
        // Devolvemos el color si se equivocó
        target.setAttribute('fill', '#0ea5e9'); 
        target.setAttribute('data-selected', 'true');
        porcionesBorradas--;
      }
    }
  }

  function comprobarPaso1() {
    let fb = document.getElementById('fb-mensaje-resta');

    if (porcionesBorradas === ej.n2) {
      fase = 2; // Avanzar
      fb.style.color = '#10b981';
      fb.innerHTML = '✓ ¡Bien! Has restado la cantidad correcta del gráfico.';

      // Bloquear gráfico original
      document.querySelectorAll('#svg-frac1-resta .slice').forEach(el => el.style.cursor = 'default');

      // Animación: Activar zona de resultado
      document.getElementById('op-igual').style.opacity = '1';
      let contRes = document.getElementById('cont-frac-res');
      contRes.style.opacity = '1';
      contRes.style.background = '#f8fafc';

      // Activar inputs
      let inpN = document.getElementById('inp-num-res');
      let inpD = document.getElementById('inp-den-res');
      inpN.disabled = false; inpD.disabled = false;
      inpN.style.background = '#ffffff'; inpD.style.background = '#ffffff';

      // Actualizar instrucciones y botón
      document.getElementById('instruccion-resta').innerHTML = "Paso 2: Observa cuántas porciones quedan coloreadas y escribe la fracción resultante.";
      let btn = document.getElementById('btn-comprobar-resta');
      btn.textContent = "Comprobar Fracción Final";

      inpN.focus();

    } else {
      fb.style.color = '#ef4444';
      let exceso = porcionesBorradas > ej.n2;
      fb.innerHTML = `✗ Has borrado ${porcionesBorradas} porciones y tenías que borrar ${ej.n2}. ${exceso ? 'Te has pasado quitando.' : 'Sigue quitando porciones.'}`;
    }
  }

  function comprobarPaso2() {
    let inpN = document.getElementById('inp-num-res');
    let inpD = document.getElementById('inp-den-res');
    let valN = parseInt(inpN.value);
    let valD = parseInt(inpD.value);
    let fb = document.getElementById('fb-mensaje-resta');

    if (isNaN(valN) || isNaN(valD)) {
      fb.style.color = '#ef4444';
      fb.innerHTML = '✗ Faltan números por rellenar.';
      return;
    }

    if (valN === ej.nRes && valD === ej.d) {
      fb.style.color = '#10b981';
      fb.innerHTML = `✓ ¡Correcto! Al restar fracciones con igual denominador, se restan los numeradores (${ej.n1} - ${ej.n2}) y se mantiene el denominador (${ej.d}).`;
      document.getElementById('btn-comprobar-resta').disabled = true;
      document.getElementById('btn-comprobar-resta').style.opacity = '0.5';

      inpN.disabled = true; inpD.disabled = true;
      inpN.style.background = '#d1fae5'; inpD.style.background = '#d1fae5';
      inpN.style.borderColor = '#10b981'; inpD.style.borderColor = '#10b981';
      inpN.style.color = '#065f46'; inpD.style.color = '#065f46';
    } else {
      fb.style.color = '#ef4444';
      let msg = '✗ Incorrecto.<br><span style="font-size:1rem; font-weight:600;">';
      if (valD !== ej.d) msg += `Recuerda: El denominador se mantiene igual porque el tamaño de las divisiones no cambia.<br>`;
      if (valN !== ej.nRes) msg += `Cuenta bien las porciones azules que han quedado en el dibujo.`;
      msg += '</span>';
      fb.innerHTML = msg;
    }
  }

  function manejadorBotonComprobar() {
    if (fase === 1) comprobarPaso1();
    else if (fase === 2) comprobarPaso2();
  }

  function inicializarEventos() {
    document.getElementById('btn-nueva-resta').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-resta').addEventListener('click', manejadorBotonComprobar);

    document.getElementById('svg-frac1-resta').addEventListener('click', interactuarPorcion);

    document.getElementById('inp-den-res').addEventListener('keypress', function(e) {
      if (e.key === 'Enter' && fase === 2) comprobarPaso2();
    });

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
