<div id="frac-resta-distinto" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">Laboratorio de Restas (Distinto Denominador)</h3>
<button id="btn-nueva-restad" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px; max-width: 700px; margin: 0 auto;"><!-- Enunciado Principal -->
<div style="display: flex; justify-content: center; align-items: center; gap: 10px; margin-bottom: 25px; background: #ffffff; padding: 15px; border-radius: 12px; border: 2px dashed #94a3b8;"><span class="operador" style="font-size: 1.5rem; color: #475569;">Resta:</span>
<div id="disp-restados" style="display: flex; align-items: center; gap: 10px;"></div>
</div>
<!-- PASO 1: Calcular mcm -->
<div class="paso-panel" id="panel-paso1-resta">
<div class="paso-titulo">Paso 1: Mínimo Común Múltiplo</div>
<div style="font-size: 1.3rem; font-weight: bold; color: #0f172a;">m.c.m. ( <span id="txt-d1-resta"></span> , <span id="txt-d2-resta"></span> ) = <input type="number" id="inp-mcm-resta" class="f-input" style="width: 80px !important; margin-left: 10px !important;" placeholder="?" /></div>
</div>
<!-- PASO 2: Amplificar (Bloqueado inicialmente) -->
<div class="paso-panel" id="panel-paso2-resta" style="opacity: 0.3; pointer-events: none;">
<div class="paso-titulo">Paso 2: Fracciones Equivalentes</div>
<div style="display: flex; justify-content: center; align-items: center; gap: 10px;"><span class="frac-box"> <input type="number" id="inp-eq-n1-resta" class="f-input" placeholder="?" /> <span class="f-line"></span> <span class="f-den" id="txt-mcm1-resta" style="color: #10b981;"></span> </span> <span class="operador">-</span> <span class="frac-box"> <input type="number" id="inp-eq-n2-resta" class="f-input" placeholder="?" /> <span class="f-line"></span> <span class="f-den" id="txt-mcm2-resta" style="color: #10b981;"></span> </span></div>
</div>
<!-- PASO 3: Resta Final (Bloqueado inicialmente) -->
<div class="paso-panel" id="panel-paso3-resta" style="opacity: 0.3; pointer-events: none; border-color: #10b981; background: #f0fdf4;">
<div class="paso-titulo" style="color: #065f46; border-color: #a7f3d0;">Paso 3: Resta Final (Numeradores)</div>
<div style="display: flex; justify-content: center; align-items: center; gap: 10px;"><span class="frac-box"> <input type="number" id="inp-res-n-resta" class="f-input" placeholder="?" /> <span class="f-line" style="background: #059669;"></span> <span class="f-den" id="txt-mcm-res-resta" style="color: #059669;"></span> </span></div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-restad" class="frac-btn frac-btn-check">Comprobar m.c.m.</button>
<div id="fb-mensaje-restad" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 50px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  // Base de datos de ejercicios de resta extraída del cuaderno
  // Diseñados para que la resta siempre dé un número positivo
  const ejerciciosRestaD = [
    {n1: 6, d1: 4, n2: 3, d2: 8},
    {n1: 5, d1: 2, n2: 2, d2: 5},
    {n1: 7, d1: 3, n2: 1, d2: 6},
    {n1: 8, d1: 6, n2: 4, d2: 9},
    {n1: 4, d1: 1, n2: 2, d2: 7},
    {n1: 9, d1: 3, n2: 2, d2: 4},
    {n1: 5, d1: 2, n2: 3, d2: 6},
    {n1: 4, d1: 3, n2: 2, d2: 5},
    {n1: 7, d1: 5, n2: 6, d2: 9},
    {n1: 9, d1: 2, n2: 2, d2: 4}
  ];

  let ej = {};
  let fase = 1;

  function calcularMCD(a, b) { return b === 0 ? a : calcularMCD(b, a % b); }
  function calcularMCM(a, b) { return (a * b) / calcularMCD(a, b); }

  function renderFraccion(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function generarNuevoEjercicio() {
    fase = 1;
    let base = ejerciciosRestaD[Math.floor(Math.random() * ejerciciosRestaD.length)];

    // Mantenemos el orden original para garantizar un resultado positivo
    ej = { n1: base.n1, d1: base.d1, n2: base.n2, d2: base.d2 };

    ej.targetMcm = calcularMCM(ej.d1, ej.d2);
    ej.targetEqN1 = ej.n1 * (ej.targetMcm / ej.d1);
    ej.targetEqN2 = ej.n2 * (ej.targetMcm / ej.d2);
    ej.targetResN = ej.targetEqN1 - ej.targetEqN2; // Resta

    // UI Principal
    document.getElementById('disp-restados').innerHTML = renderFraccion(ej.n1, ej.d1) + '<span class="operador">-</span>' + renderFraccion(ej.n2, ej.d2);
    document.getElementById('txt-d1-resta').textContent = ej.d1;
    document.getElementById('txt-d2-resta').textContent = ej.d2;

    // Resetear Paneles
    document.getElementById('panel-paso1-resta').style.opacity = '1';
    document.getElementById('panel-paso1-resta').style.pointerEvents = 'auto';

    document.getElementById('panel-paso2-resta').style.opacity = '0.3';
    document.getElementById('panel-paso2-resta').style.pointerEvents = 'none';

    document.getElementById('panel-paso3-resta').style.opacity = '0.3';
    document.getElementById('panel-paso3-resta').style.pointerEvents = 'none';

    // Resetear Inputs
    ['inp-mcm-resta', 'inp-eq-n1-resta', 'inp-eq-n2-resta', 'inp-res-n-resta'].forEach(id => {
      let el = document.getElementById(id);
      el.value = '';
      el.disabled = false;
      el.style.background = '#f8fafc';
      el.style.borderColor = '#94a3b8';
      el.style.color = '#0284c7';
    });

    // Etiquetas fijas
    document.getElementById('txt-mcm1-resta').textContent = '?';
    document.getElementById('txt-mcm2-resta').textContent = '?';
    document.getElementById('txt-mcm-res-resta').textContent = '?';

    // Botón y Feedback
    let btn = document.getElementById('btn-comprobar-restad');
    btn.textContent = "Comprobar m.c.m.";
    btn.disabled = false;
    btn.style.opacity = '1';

    document.getElementById('fb-mensaje-restad').innerHTML = '';
    document.getElementById('inp-mcm-resta').focus();
  }

  function comprobarPaso1() {
    let inp = document.getElementById('inp-mcm-resta');
    let val = parseInt(inp.value);
    let fb = document.getElementById('fb-mensaje-restad');

    if (isNaN(val)) { fb.style.color = '#ef4444'; fb.innerHTML = '✗ Escribe el m.c.m.'; return; }

    if (val === ej.targetMcm) {
      fase = 2;
      fb.style.color = '#10b981';
      fb.innerHTML = `✓ ¡Bien! El m.c.m. de ${ej.d1} y ${ej.d2} es ${ej.targetMcm}. Ahora encuentra los nuevos numeradores para restar.`;

      inp.disabled = true;
      inp.style.background = '#d1fae5';
      inp.style.borderColor = '#10b981';
      inp.style.color = '#065f46';

      // Desbloquear Paso 2
      document.getElementById('panel-paso2-resta').style.opacity = '1';
      document.getElementById('panel-paso2-resta').style.pointerEvents = 'auto';
      document.getElementById('txt-mcm1-resta').textContent = ej.targetMcm;
      document.getElementById('txt-mcm2-resta').textContent = ej.targetMcm;

      let btn = document.getElementById('btn-comprobar-restad');
      btn.textContent = "Comprobar Equivalentes";
      document.getElementById('inp-eq-n1-resta').focus();

    } else {
      fb.style.color = '#ef4444';
      fb.innerHTML = `✗ Incorrecto. Revisa la factorización de ${ej.d1} y ${ej.d2} para hallar el m.c.m.`;
    }
  }

  function comprobarPaso2() {
    let in1 = document.getElementById('inp-eq-n1-resta');
    let in2 = document.getElementById('inp-eq-n2-resta');
    let v1 = parseInt(in1.value);
    let v2 = parseInt(in2.value);
    let fb = document.getElementById('fb-mensaje-restad');

    if (isNaN(v1) || isNaN(v2)) { fb.style.color = '#ef4444'; fb.innerHTML = '✗ Faltan numeradores por rellenar.'; return; }

    let ok1 = (v1 === ej.targetEqN1);
    let ok2 = (v2 === ej.targetEqN2);

    if (ok1 && ok2) {
      fase = 3;
      fb.style.color = '#10b981';
      fb.innerHTML = `✓ ¡Excelente! Has amplificado correctamente. Ya tienes el mismo denominador, procede a restar.`;

      in1.disabled = true; in2.disabled = true;
      in1.style.background = '#d1fae5'; in2.style.background = '#d1fae5';
      in1.style.borderColor = '#10b981'; in2.style.borderColor = '#10b981';
      in1.style.color = '#065f46'; in2.style.color = '#065f46';

      // Desbloquear Paso 3
      document.getElementById('panel-paso3-resta').style.opacity = '1';
      document.getElementById('panel-paso3-resta').style.pointerEvents = 'auto';
      document.getElementById('txt-mcm-res-resta').textContent = ej.targetMcm;

      let btn = document.getElementById('btn-comprobar-restad');
      btn.textContent = "Comprobar Resta Final";
      document.getElementById('inp-res-n-resta').focus();

    } else {
      fb.style.color = '#ef4444';
      let msg = '✗ Hay errores.<br><span style="font-size:1rem; font-weight:600;">';
      if (!ok1) msg += `Fracción 1: Divide ${ej.targetMcm} entre ${ej.d1} y multiplica por ${ej.n1}.<br>`;
      if (!ok2) msg += `Fracción 2: Divide ${ej.targetMcm} entre ${ej.d2} y multiplica por ${ej.n2}.`;
      msg += '</span>';
      fb.innerHTML = msg;
    }
  }

  function comprobarPaso3() {
    let inp = document.getElementById('inp-res-n-resta');
    let val = parseInt(inp.value);
    let fb = document.getElementById('fb-mensaje-restad');

    if (isNaN(val)) { fb.style.color = '#ef4444'; fb.innerHTML = '✗ Escribe el numerador final.'; return; }

    if (val === ej.targetResN) {
      fb.style.color = '#10b981';
      fb.innerHTML = `✓ ¡Enhorabuena! Has completado todo el proceso de resta con distinto denominador con éxito.`;

      inp.disabled = true;
      inp.style.background = '#d1fae5';
      inp.style.borderColor = '#10b981';
      inp.style.color = '#065f46';

      let btn = document.getElementById('btn-comprobar-restad');
      btn.disabled = true;
      btn.style.opacity = '0.5';
    } else {
      fb.style.color = '#ef4444';
      fb.innerHTML = `✗ Incorrecto. Solo tienes que restar los numeradores equivalentes que calculaste en el paso 2.`;
    }
  }

  function manejadorBotonComprobar() {
    if (fase === 1) comprobarPaso1();
    else if (fase === 2) comprobarPaso2();
    else if (fase === 3) comprobarPaso3();
  }

  function inicializarEventos() {
    document.getElementById('btn-nueva-restad').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-restad').addEventListener('click', manejadorBotonComprobar);

    // Soporte Enter para inputs de cada fase
    document.getElementById('inp-mcm-resta').addEventListener('keypress', e => { if (e.key === 'Enter' && fase === 1) comprobarPaso1(); });
    document.getElementById('inp-eq-n2-resta').addEventListener('keypress', e => { if (e.key === 'Enter' && fase === 2) comprobarPaso2(); });
    document.getElementById('inp-res-n-resta').addEventListener('keypress', e => { if (e.key === 'Enter' && fase === 3) comprobarPaso3(); });

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

