<div id="frac-resta-entero" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">El Transformador: Entero menos Fracción</h3>
<button id="btn-nuevo-ent" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px; max-width: 700px; margin: 0 auto;"><!-- Enunciado Principal -->
<div style="display: flex; justify-content: center; align-items: center; gap: 10px; margin-bottom: 25px; background: #ffffff; padding: 25px; border-radius: 12px; border: 2px dashed #94a3b8;">
<div id="disp-resta-ent" style="display: flex; align-items: center; gap: 15px;"></div>
</div>
<!-- PASO 1: Convertir el entero -->
<div class="paso-panel" id="panel-paso1-ent">
<div class="paso-titulo">Paso 1: Convierte el número natural en fracción</div>
<p style="font-size: 0.95rem; color: #475569; margin-top: 0; margin-bottom: 15px;">Transforma el número <span id="txt-entero" style="font-weight: bold; color: #0ea5e9;"></span> en una fracción equivalente que tenga denominador <span id="txt-den-obj" style="font-weight: bold; color: #0f172a;"></span> para poder restar.</p>
<div style="display: flex; justify-content: center; align-items: center; gap: 15px;"><span class="entero-gigante" id="txt-entero-form"></span> <span class="operador" style="font-size: 1.5rem;">=</span> <span class="frac-box"> <input type="number" id="inp-ent-n" class="f-input" placeholder="?" /> <span class="f-line"></span> <span class="f-den" id="txt-ent-d"></span> </span></div>
</div>
<!-- PASO 2: Resta Final (Bloqueado inicialmente) -->
<div class="paso-panel" id="panel-paso2-ent" style="opacity: 0.3; pointer-events: none; border-color: #10b981; background: #f0fdf4;">
<div class="paso-titulo" style="color: #065f46; border-color: #a7f3d0;">Paso 2: Resta Final</div>
<div style="display: flex; justify-content: center; align-items: center; gap: 10px;">
<div id="disp-resta-final" style="display: flex; align-items: center; gap: 10px;"></div>
<span class="operador">=</span> <span class="frac-box"> <input type="number" id="inp-res-n-ent" class="f-input" placeholder="?" /> <span class="f-line" style="background: #059669;"></span> <span class="f-den" id="txt-res-d" style="color: #059669;"></span> </span></div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-ent" class="frac-btn frac-btn-check">Comprobar Conversión</button>
<div id="fb-mensaje-ent" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 50px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  const ejerciciosEnt = [
    {e: 1, n: 2, d: 5},
    {e: 4, n: 4, d: 9},
    {e: 2, n: 5, d: 6},
    {e: 3, n: 1, d: 3},
    {e: 8, n: 6, d: 8},
    {e: 5, n: 4, d: 5},
    {e: 1, n: 8, d: 9},
    {e: 4, n: 5, d: 7},
    {e: 7, n: 1, d: 4},
    {e: 5, n: 4, d: 9},
    {e: 9, n: 3, d: 5},
    {e: 6, n: 7, d: 8}
  ];

  let ej = {};
  let fase = 1;

  function renderFraccion(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function generarNuevoEjercicio() {
    fase = 1;
    let base = ejerciciosEnt[Math.floor(Math.random() * ejerciciosEnt.length)];

    // Aleatorizar valores basándose en el cuaderno, asegurando natural - fracción
    ej.e = Math.floor(Math.random() * 9) + 1;
    ej.d = Math.floor(Math.random() * 7) + 3; 
    ej.n = Math.floor(Math.random() * (ej.d - 1)) + 1; // Para que la fracción sea propia

    ej.targetEqN = ej.e * ej.d;
    ej.targetResN = ej.targetEqN - ej.n;

    // UI Principal
    let htmlResta = '<span class="entero-gigante">' + ej.e + '</span><span class="operador">-</span>' + renderFraccion(ej.n, ej.d);

    document.getElementById('disp-resta-ent').innerHTML = htmlResta;

    document.getElementById('txt-entero').textContent = ej.e;
    document.getElementById('txt-entero-form').textContent = ej.e;
    document.getElementById('txt-den-obj').textContent = ej.d;
    document.getElementById('txt-ent-d').textContent = ej.d;

    // Resetear Paneles
    document.getElementById('panel-paso1-ent').style.opacity = '1';
    document.getElementById('panel-paso1-ent').style.pointerEvents = 'auto';

    document.getElementById('panel-paso2-ent').style.opacity = '0.3';
    document.getElementById('panel-paso2-ent').style.pointerEvents = 'none';

    // Resetear Inputs
    ['inp-ent-n', 'inp-res-n-ent'].forEach(id => {
      let el = document.getElementById(id);
      el.value = '';
      el.disabled = false;
      el.style.background = '#f8fafc';
      el.style.borderColor = '#94a3b8';
      el.style.color = '#0284c7';
    });

    document.getElementById('txt-res-d').textContent = '?';
    document.getElementById('disp-resta-final').innerHTML = '';

    // Botón y Feedback
    let btn = document.getElementById('btn-comprobar-ent');
    btn.textContent = "Comprobar Conversión";
    btn.disabled = false;
    btn.style.opacity = '1';

    document.getElementById('fb-mensaje-ent').innerHTML = '';
    document.getElementById('inp-ent-n').focus();
  }

  function comprobarPaso1() {
    let inp = document.getElementById('inp-ent-n');
    let val = parseInt(inp.value);
    let fb = document.getElementById('fb-mensaje-ent');

    if (isNaN(val)) { fb.style.color = '#ef4444'; fb.innerHTML = '✗ Escribe el numerador de la fracción equivalente.'; return; }

    if (val === ej.targetEqN) {
      fase = 2;
      fb.style.color = '#10b981';
      fb.innerHTML = `✓ ¡Bien! El número ${ej.e} equivale a la fracción ${ej.targetEqN}/${ej.d}. Ahora realiza la resta.`;

      inp.disabled = true;
      inp.style.background = '#d1fae5';
      inp.style.borderColor = '#10b981';
      inp.style.color = '#065f46';

      // Desbloquear Paso 2
      document.getElementById('panel-paso2-ent').style.opacity = '1';
      document.getElementById('panel-paso2-ent').style.pointerEvents = 'auto';

      // Montar la ecuación del paso 2
      let htmlPaso2 = renderFraccion(ej.targetEqN, ej.d) + '<span class="operador" style="font-size: 1.5rem;">-</span>' + renderFraccion(ej.n, ej.d);

      document.getElementById('disp-resta-final').innerHTML = htmlPaso2;
      document.getElementById('txt-res-d').textContent = ej.d;

      let btn = document.getElementById('btn-comprobar-ent');
      btn.textContent = "Comprobar Resta";
      document.getElementById('inp-res-n-ent').focus();

    } else {
      fb.style.color = '#ef4444';
      fb.innerHTML = `✗ Incorrecto. Para convertir el número natural en fracción, debes multiplicar el entero (${ej.e}) por el denominador objetivo (${ej.d}).`;
    }
  }

  function comprobarPaso2() {
    let inp = document.getElementById('inp-res-n-ent');
    let val = parseInt(inp.value);
    let fb = document.getElementById('fb-mensaje-ent');

    if (isNaN(val)) { fb.style.color = '#ef4444'; fb.innerHTML = '✗ Escribe el numerador final.'; return; }

    if (val === ej.targetResN) {
      fb.style.color = '#10b981';
      fb.innerHTML = `✓ ¡Excelente! Has resuelto la resta transformando previamente el número natural.`;

      inp.disabled = true;
      inp.style.background = '#d1fae5';
      inp.style.borderColor = '#10b981';
      inp.style.color = '#065f46';

      let btn = document.getElementById('btn-comprobar-ent');
      btn.disabled = true;
      btn.style.opacity = '0.5';
    } else {
      fb.style.color = '#ef4444';
      fb.innerHTML = `✗ Error en la resta. Fíjate en los numeradores del Paso 2 (${ej.targetEqN} - ${ej.n}).`;
    }
  }

  function manejadorBotonComprobar() {
    if (fase === 1) comprobarPaso1();
    else if (fase === 2) comprobarPaso2();
  }

  function inicializarEventos() {
    document.getElementById('btn-nuevo-ent').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-ent').addEventListener('click', manejadorBotonComprobar);

    document.getElementById('inp-ent-n').addEventListener('keypress', e => { if (e.key === 'Enter' && fase === 1) comprobarPaso1(); });
    document.getElementById('inp-res-n-ent').addEventListener('keypress', e => { if (e.key === 'Enter' && fase === 2) comprobarPaso2(); });

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

