<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">La Máquina de Multiplicar</h3>
<button id="btn-nuevo-mult-f" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 30px;">Calcula el producto de las dos fracciones y escribe el resultado <span style="font-size: 0.95rem; font-weight: normal;">(sin simplificar)</span>:</p>
<div style="position: relative; display: inline-flex; justify-content: center; align-items: center; gap: 10px; flex-wrap: wrap; background: #ffffff; padding: 30px 40px; border-radius: 12px; border: 2px dashed #cbd5e1; box-shadow: 0 4px 6px rgba(0,0,0,0.05); margin: 0 auto;"><!-- SVGs para feedback visual (Ajustado a la imagen) --> <svg id="svg-guias" class="guia-svg"> <!-- Línea superior (Numeradores) - Color naranja/mostaza como en la imagen --> <path d="M 40,25 Q 120,5 200,25" fill="none" stroke="#f59e0b" stroke-width="3" stroke-dasharray="6,4" marker-end="url(#arrowhead-top)"></path> <!-- Línea inferior (Denominadores) - Color morado como en la imagen --> <path d="M 40,75 Q 120,95 200,75" fill="none" stroke="#8b5cf6" stroke-width="3" stroke-dasharray="6,4" marker-end="url(#arrowhead-bottom)"></path> <defs> <marker id="arrowhead-top" markerwidth="6" markerheight="6" refx="5" refy="3" orient="auto"> <polygon points="0 0, 6 3, 0 6" fill="#f59e0b"></polygon> </marker> <marker id="arrowhead-bottom" markerwidth="6" markerheight="6" refx="5" refy="3" orient="auto"> <polygon points="0 0, 6 3, 0 6" fill="#8b5cf6"></polygon> </marker> </defs> </svg> <!-- Fracción 1 --> <span class="frac-box" id="fb-f1"> <span class="f-num" id="f1-n"></span> <span class="f-line"></span> <span class="f-den" id="f1-d"></span> </span> <span class="operador">×</span> <!-- Fracción 2 --> <span class="frac-box" id="fb-f2"> <span class="f-num" id="f2-n"></span> <span class="f-line"></span> <span class="f-den" id="f2-d"></span> </span> <span class="operador" style="color: #64748b;">=</span> <!-- Resultado Interactivo --> <span class="frac-box" id="fb-res"> <input type="number" id="inp-res-n-multf" class="f-input" placeholder="?" /> <span class="f-line" style="background: #0f172a;"></span> <input type="number" id="inp-res-d-multf" class="f-input" placeholder="?" /> </span></div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-mult-f" class="frac-btn frac-btn-check">Comprobar Multiplicación</button>
<div id="fb-mensaje-mult-f" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 50px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  // Base de datos de ejercicios basada en el cuaderno (Fracción x Fracción)
  const ejerciciosMultF = [
    {n1: 6, d1: 4, n2: 3, d2: 8},
    {n1: 8, d1: 6, n2: 4, d2: 9},
    {n1: 5, d1: 2, n2: 2, d2: 5},
    {n1: 4, d1: 1, n2: 2, d2: 7},
    {n1: 7, d1: 3, n2: 1, d2: 6},
    {n1: 9, d1: 3, n2: 2, d2: 4},
    {n1: 5, d1: 2, n2: 3, d2: 6},
    {n1: 8, d1: 7, n2: 5, d2: 3},
    {n1: 4, d1: 3, n2: 2, d2: 5},
    {n1: 9, d1: 2, n2: 2, d2: 4},
    {n1: 7, d1: 5, n2: 6, d2: 9},
    {n1: 10, d1: 8, n2: 6, d2: 11}
  ];

  let ej = {};

  function calcularMCD(a, b) { return b === 0 ? a : calcularMCD(b, a % b); }

  function generarNuevoEjercicio() {
    let base = ejerciciosMultF[Math.floor(Math.random() * ejerciciosMultF.length)];

    ej.n1 = base.n1;
    ej.d1 = base.d1;

    // Aleatorizar un poco la segunda fracción a partir de la base
    ej.n2 = base.n2;
    ej.d2 = base.d2;

    // Posibilidad de intercambiar para variar el catálogo
    if (Math.random() > 0.5) {
        let tempN = ej.n1; let tempD = ej.d1;
        ej.n1 = ej.n2; ej.d1 = ej.d2;
        ej.n2 = tempN; ej.d2 = tempD;
    }

    ej.targetResN = ej.n1 * ej.n2;
    ej.targetResD = ej.d1 * ej.d2;

    // Pintar UI
    document.getElementById('f1-n').textContent = ej.n1;
    document.getElementById('f1-d').textContent = ej.d1;
    document.getElementById('f2-n').textContent = ej.n2;
    document.getElementById('f2-d').textContent = ej.d2;

    // Resetear colores
    document.getElementById('f1-n').style.color = '#0f172a';
    document.getElementById('f2-n').style.color = '#0f172a';
    document.getElementById('f1-d').style.color = '#0f172a';
    document.getElementById('f2-d').style.color = '#0f172a';

    // Ocultar guías
    document.getElementById('svg-guias').style.display = 'none';

    // Resetear Inputs
    ['inp-res-n-multf', 'inp-res-d-multf'].forEach(id => {
      let el = document.getElementById(id);
      el.value = '';
      el.disabled = false;
      el.style.background = '#f8fafc';
      el.style.borderColor = '#94a3b8';
      el.style.color = '#0284c7';
    });

    let btn = document.getElementById('btn-comprobar-mult-f');
    btn.disabled = false;
    btn.style.opacity = '1';

    document.getElementById('fb-mensaje-mult-f').innerHTML = '';
    document.getElementById('inp-res-n-multf').focus();
  }

  function reposicionarGuias() {
    // Calcula dinámicamente las posiciones para el SVG
    let svg = document.getElementById('svg-guias');
    let f1 = document.getElementById('fb-f1');
    let f2 = document.getElementById('fb-f2');
    let res = document.getElementById('fb-res');

    // Obtener coordenadas relativas al contenedor
    let contenedor = svg.parentElement;
    let rectCont = contenedor.getBoundingClientRect();
    let rectF1 = f1.getBoundingClientRect();
    let rectF2 = f2.getBoundingClientRect();
    let rectRes = res.getBoundingClientRect();

    let centroF1x = rectF1.left - rectCont.left + (rectF1.width / 2);
    let centroF2x = rectF2.left - rectCont.left + (rectF2.width / 2);
    let centroResx = rectRes.left - rectCont.left + 15; // Ajuste apuntando al input

    // Dibujar curvas corrigiendo la posición de la curva morada inferior (apuntando al denominador)
    svg.innerHTML = `
      <path d="M ${centroF1x},25 Q ${centroF2x},5 ${centroResx},25" fill="none" stroke="#f59e0b" stroke-width="3" stroke-dasharray="6,4" marker-end="url(#arrowhead-top)"/>
      <path d="M ${centroF1x},75 Q ${centroF2x},95 ${centroResx},85" fill="none" stroke="#8b5cf6" stroke-width="3" stroke-dasharray="6,4" marker-end="url(#arrowhead-bottom)"/>
      <defs>
        <marker id="arrowhead-top" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
          <polygon points="0 0, 6 3, 0 6" fill="#f59e0b" />
        </marker>
        <marker id="arrowhead-bottom" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
          <polygon points="0 0, 6 3, 0 6" fill="#8b5cf6" />
        </marker>
      </defs>
    `;
  }

  function comprobarResultado() {
    let inN = document.getElementById('inp-res-n-multf');
    let inD = document.getElementById('inp-res-d-multf');
    let valN = parseInt(inN.value);
    let valD = parseInt(inD.value);
    let fb = document.getElementById('fb-mensaje-mult-f');

    if (isNaN(valN) || isNaN(valD)) { 
      fb.style.color = '#ef4444'; 
      fb.innerHTML = '✗ Faltan números por rellenar en el resultado.'; 
      return; 
    }

    let okN = (valN === ej.targetResN);
    let okD = (valD === ej.targetResD);

    // Comprobar si el alumno lo simplificó (aunque se pide sin simplificar)
    let dCom = calcularMCD(ej.targetResN, ej.targetResD);
    let simplificadoOk = (valN === (ej.targetResN / dCom)) && (valD === (ej.targetResD / dCom));

    if ((okN && okD) || simplificadoOk) {
      fb.style.color = '#10b981';
      fb.innerHTML = `✓ ¡Correcto! El producto de dos fracciones se realiza multiplicando en línea.`;

      inN.disabled = true; inD.disabled = true;
      inN.style.background = '#d1fae5'; inD.style.background = '#d1fae5';
      inN.style.borderColor = '#10b981'; inD.style.borderColor = '#10b981';
      inN.style.color = '#065f46'; inD.style.color = '#065f46';

      document.getElementById('svg-guias').style.display = 'none';
      document.getElementById('f1-n').style.color = '#0f172a';
      document.getElementById('f2-n').style.color = '#0f172a';
      document.getElementById('f1-d').style.color = '#0f172a';
      document.getElementById('f2-d').style.color = '#0f172a';

      let btn = document.getElementById('btn-comprobar-mult-f');
      btn.disabled = true;
      btn.style.opacity = '0.5';
    } else {
      fb.style.color = '#ef4444';
      let msg = '✗ Incorrecto.<br><span style="font-size:1rem; font-weight:600;">';

      // Mostrar guías
      document.getElementById('svg-guias').style.display = 'block';
      reposicionarGuias();

      if (!okN) {
        msg += `Numerador: Multiplica en línea (${ej.n1} × ${ej.n2}).<br>`;
        document.getElementById('f1-n').style.color = '#f59e0b';
        document.getElementById('f2-n').style.color = '#f59e0b';
      } else {
        document.getElementById('f1-n').style.color = '#10b981';
        document.getElementById('f2-n').style.color = '#10b981';
      }

      if (!okD) {
        msg += `Denominador: Multiplica en línea (${ej.d1} × ${ej.d2}).`;
        document.getElementById('f1-d').style.color = '#8b5cf6';
        document.getElementById('f2-d').style.color = '#8b5cf6';
      } else {
        document.getElementById('f1-d').style.color = '#10b981';
        document.getElementById('f2-d').style.color = '#10b981';
      }

      msg += '</span>';
      fb.innerHTML = msg;
    }
  }

  function inicializarEventos() {
    document.getElementById('btn-nuevo-mult-f').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-mult-f').addEventListener('click', comprobarResultado);

    // Soporte Enter
    document.getElementById('inp-res-d-multf').addEventListener('keypress', e => { 
      if (e.key === 'Enter') comprobarResultado(); 
    });

    // Reposicionar guías si la ventana cambia de tamaño
    window.addEventListener('resize', () => {
        if (document.getElementById('svg-guias').style.display === 'block') {
            reposicionarGuias();
        }
    });

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

