<div id="frac-mult-entero" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">Multiplicador Entero-Fracción</h3>
<button id="btn-nuevo-mult-e" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 30px;">Multiplica el número natural por la fracción y escribe el resultado <span style="font-size: 0.95rem; font-weight: normal;">(sin simplificar)</span>:</p>
<div style="display: flex; justify-content: center; align-items: center; gap: 10px; flex-wrap: wrap; background: #ffffff; padding: 30px; border-radius: 12px; border: 2px dashed #cbd5e1; box-shadow: 0 4px 6px rgba(0,0,0,0.05); max-width: 600px; margin: 0 auto;"><!-- Planteamiento -->
<div id="disp-mult-planteamiento" style="display: flex; align-items: center; gap: 10px;"><!-- Se inyecta por JS para permitir alternar el orden --></div>
<span class="operador" style="color: #64748b;">=</span> <!-- Resultado Interactivo --> <span class="frac-box"> <input type="number" id="inp-res-n-mult" class="f-input" placeholder="?" /> <span class="f-line" style="background: #0f172a;"></span> <input type="number" id="inp-res-d-mult" class="f-input" placeholder="?" /> </span></div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-mult-e" class="frac-btn frac-btn-check">Comprobar Multiplicación</button>
<div id="fb-mensaje-mult-e" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 50px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  // Base de datos de ejercicios basada en el cuaderno
  const ejerciciosMultE = [
    {e: 3, n: 4, d: 6},
    {e: 6, n: 2, d: 7},
    {e: 7, n: 1, d: 5},
    {e: 5, n: 3, d: 2},
    {e: 8, n: 2, d: 9},
    {e: 4, n: 9, d: 6},
    {e: 3, n: 1, d: 3},
    {e: 4, n: 5, d: 3},
    {e: 4, n: 5, d: 4},
    {e: 5, n: 2, d: 6},
    {e: 2, n: 7, d: 4},
    {e: 8, n: 4, d: 9},
    {e: 9, n: 3, d: 10}
  ];

  let ej = {};

  function renderFraccion(n, d) {
    return `
      <span class="frac-box">
        <span class="f-num">${n}</span>
        <span class="f-line"></span>
        <span class="f-den">${d}</span>
      </span>
    `;
  }

  function generarNuevoEjercicio() {
    let base = ejerciciosMultE[Math.floor(Math.random() * ejerciciosMultE.length)];

    ej.e = base.e;
    ej.n = base.n;
    ej.d = base.d;

    // Aleatorizar si el entero va primero o segundo para mayor versatilidad
    ej.orden = (Math.random() > 0.5) ? 'ef' : 'fe';

    ej.targetResN = ej.e * ej.n;
    ej.targetResD = ej.d;

    // Pintar UI del planteamiento
    let htmlPlanteamiento = '';
    if (ej.orden === 'ef') {
      htmlPlanteamiento = `<span class="entero-gigante">${ej.e}</span><span class="operador">×</span>${renderFraccion(ej.n, ej.d)}`;
    } else {
      htmlPlanteamiento = `${renderFraccion(ej.n, ej.d)}<span class="operador">×</span><span class="entero-gigante">${ej.e}</span>`;
    }

    document.getElementById('disp-mult-planteamiento').innerHTML = htmlPlanteamiento;

    // Resetear Inputs
    ['inp-res-n-mult', 'inp-res-d-mult'].forEach(id => {
      let el = document.getElementById(id);
      el.value = '';
      el.disabled = false;
      el.style.background = '#f8fafc';
      el.style.borderColor = '#94a3b8';
      el.style.color = '#0284c7';
    });

    let btn = document.getElementById('btn-comprobar-mult-e');
    btn.disabled = false;
    btn.style.opacity = '1';

    document.getElementById('fb-mensaje-mult-e').innerHTML = '';
    document.getElementById('inp-res-n-mult').focus();
  }

  function comprobarResultado() {
    let inN = document.getElementById('inp-res-n-mult');
    let inD = document.getElementById('inp-res-d-mult');
    let valN = parseInt(inN.value);
    let valD = parseInt(inD.value);
    let fb = document.getElementById('fb-mensaje-mult-e');

    if (isNaN(valN) || isNaN(valD)) { 
      fb.style.color = '#ef4444'; 
      fb.innerHTML = '✗ Faltan números por rellenar en la fracción final.'; 
      return; 
    }

    let okN = (valN === ej.targetResN);
    let okD = (valD === ej.targetResD);

    if (okN && okD) {
      fb.style.color = '#10b981';
      fb.innerHTML = `✓ ¡Correcto! El número natural (${ej.e}) solo multiplica al numerador (${ej.n}).`;

      inN.disabled = true; inD.disabled = true;
      inN.style.background = '#d1fae5'; inD.style.background = '#d1fae5';
      inN.style.borderColor = '#10b981'; inD.style.borderColor = '#10b981';
      inN.style.color = '#065f46'; inD.style.color = '#065f46';

      let btn = document.getElementById('btn-comprobar-mult-e');
      btn.disabled = true;
      btn.style.opacity = '0.5';
    } else {
      fb.style.color = '#ef4444';
      let msg = '✗ Incorrecto.<br><span style="font-size:1rem; font-weight:600;">';

      if (!okD && valD === (ej.e * ej.d)) {
        msg += `Has multiplicado también el denominador. Recuerda: el entero solo multiplica a la parte de arriba.<br>`;
      } else if (!okD) {
        msg += `El denominador es incorrecto. Debe mantenerse exactamente igual que en la fracción original.<br>`;
      }

      if (!okN) {
        msg += `El numerador es incorrecto. Debes multiplicar ${ej.e} × ${ej.n}.`;
      }

      msg += '</span>';
      fb.innerHTML = msg;
    }
  }

  function inicializarEventos() {
    document.getElementById('btn-nuevo-mult-e').addEventListener('click', generarNuevoEjercicio);
    document.getElementById('btn-comprobar-mult-e').addEventListener('click', comprobarResultado);

    // Soporte Enter en el input inferior
    document.getElementById('inp-res-d-mult').addEventListener('keypress', e => { 
      if (e.key === 'Enter') comprobarResultado(); 
    });

    generarNuevoEjercicio();
  }

  setTimeout(inicializarEventos, 150);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

