<div id="frac-mult-desafio" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">El Desafío del Inspector</h3>
<button id="btn-iniciar-desafio" class="frac-btn">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 30px;">Revisa la siguiente multiplicación. Como profesor, decide si está bien resuelta o si contiene un error:</p>
<div class="marco-actividad-desafio"><!-- Maquetación ESTATICA de Fracciones -->
<div class="frac-box">
<div id="txt-desafio-n1" class="f-num">3</div>
<div class="f-line"><br /></div>
<div id="txt-desafio-d1" class="f-den">8</div>
</div>
<div class="operador">×</div>
<div class="frac-box">
<div id="txt-desafio-n2" class="f-num">6</div>
<div class="f-line"><br /></div>
<div id="txt-desafio-d2" class="f-den">4</div>
</div>
<div class="operador" style="color: #64748b;">=</div>
<!-- Resultado Mostrado -->
<div class="frac-box">
<div id="txt-desafio-res-n" class="f-num" style="color: #0284c7;">18</div>
<div class="f-line" style="background: #0f172a;"><br /></div>
<div id="txt-desafio-res-d" class="f-den" style="color: #0284c7;">32</div>
</div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;">
<div style="display: flex; justify-content: center; gap: 15px; margin-bottom: 20px;"><button id="btn-correcto-desafio" class="frac-btn" style="background-color: #10b981 !important; border-color: #059669 !important;">✔️ Correcto</button> <button id="btn-error-desafio" class="frac-btn" style="background-color: #ef4444 !important; border-color: #dc2626 !important;">❌ Hay un Error</button></div>
<div id="mensaje-estado-desafio" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 50px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  const ejBaseDesafio = [
    {n1: 6, d1: 4, n2: 3, d2: 8},
    {n1: 8, d1: 6, n2: 4, d2: 9},
    {n1: 5, d1: 2, n2: 2, d2: 5},
    {n1: 4, d1: 1, n2: 2, d2: 7},
    {n1: 7, d1: 3, n2: 1, d2: 6},
    {n1: 9, d1: 3, n2: 2, d2: 4},
    {n1: 5, d1: 2, n2: 3, d2: 6},
    {n1: 8, d1: 7, n2: 5, d2: 3},
    {n1: 4, d1: 3, n2: 2, d2: 5},
    {n1: 9, d1: 2, n2: 2, d2: 4},
    {n1: 7, d1: 5, n2: 6, d2: 9},
    {n1: 10, d1: 8, n2: 6, d2: 11}
  ];

  let metaDesafio = {};
  let evaluadoDesafio = false;

  function montarProblemaDesafio() {
    evaluadoDesafio = false;
    let base = ejBaseDesafio[Math.floor(Math.random() * ejBaseDesafio.length)];

    metaDesafio.n1 = base.n1; 
    metaDesafio.d1 = base.d1;
    metaDesafio.n2 = base.n2; 
    metaDesafio.d2 = base.d2;

    // Aleatorizar si se muestra correcto o con error (aprox 50% de probabilidad)
    metaDesafio.esCorrecto = Math.random() > 0.5;

    if (metaDesafio.esCorrecto) {
        metaDesafio.resN = metaDesafio.n1 * metaDesafio.n2;
        metaDesafio.resD = metaDesafio.d1 * metaDesafio.d2;
        metaDesafio.motivoError = null;
    } else {
        // Generar un error común
        let tipoError = Math.random();
        if (tipoError < 0.33) {
            // Error: Multiplicar en cruz (como en la división)
            metaDesafio.resN = metaDesafio.n1 * metaDesafio.d2;
            metaDesafio.resD = metaDesafio.d1 * metaDesafio.n2;
            metaDesafio.motivoError = "multiplico_cruz";
        } else if (tipoError < 0.66) {
            // Error: Sumar denominadores
            metaDesafio.resN = metaDesafio.n1 * metaDesafio.n2;
            metaDesafio.resD = metaDesafio.d1 + metaDesafio.d2;
            metaDesafio.motivoError = "sumo_denominadores";
        } else {
            // Error: Solo multiplicar numeradores (copiar un denominador)
            metaDesafio.resN = metaDesafio.n1 * metaDesafio.n2;
            metaDesafio.resD = metaDesafio.d1;
            metaDesafio.motivoError = "copio_denominador";
        }
    }

    // Actualizamos textos (NUNCA insertamos HTML nuevo)
    document.getElementById('txt-desafio-n1').innerText = metaDesafio.n1;
    document.getElementById('txt-desafio-d1').innerText = metaDesafio.d1;
    document.getElementById('txt-desafio-n2').innerText = metaDesafio.n2;
    document.getElementById('txt-desafio-d2').innerText = metaDesafio.d2;

    document.getElementById('txt-desafio-res-n').innerText = metaDesafio.resN;
    document.getElementById('txt-desafio-res-d').innerText = metaDesafio.resD;

    // Habilitar botones
    document.getElementById('btn-correcto-desafio').disabled = false;
    document.getElementById('btn-correcto-desafio').style.opacity = '1';
    document.getElementById('btn-error-desafio').disabled = false;
    document.getElementById('btn-error-desafio').style.opacity = '1';

    document.getElementById('mensaje-estado-desafio').innerHTML = '';
  }

  function comprobarSolucionDesafio(respuestaAlumnoCorrecto) {
    if (evaluadoDesafio) return;
    evaluadoDesafio = true;

    let msj = document.getElementById('mensaje-estado-desafio');

    // Deshabilitar botones
    document.getElementById('btn-correcto-desafio').disabled = true;
    document.getElementById('btn-correcto-desafio').style.opacity = '0.5';
    document.getElementById('btn-error-desafio').disabled = true;
    document.getElementById('btn-error-desafio').style.opacity = '0.5';

    if (respuestaAlumnoCorrecto === metaDesafio.esCorrecto) {
        msj.style.color = '#10b981';
        let textoAcierto = '🎉 ¡Excelente vista de lince! ';

        if (metaDesafio.esCorrecto) {
            textoAcierto += 'La operación estaba perfectamente multiplicada en línea.';
        } else {
            textoAcierto += 'Efectivamente, había un gazapo. ';
            if (metaDesafio.motivoError === "multiplico_cruz") {
                textoAcierto += `Han multiplicado en cruz (${metaDesafio.n1}×${metaDesafio.d2} y ${metaDesafio.d1}×${metaDesafio.n2}), eso se hace en las divisiones.`;
            } else if (metaDesafio.motivoError === "sumo_denominadores") {
                textoAcierto += `Han sumado los denominadores (${metaDesafio.d1}+${metaDesafio.d2}), y debían multiplicarlos.`;
            } else {
                textoAcierto += `Se han olvidado de multiplicar los denominadores (${metaDesafio.d1}×${metaDesafio.d2}).`;
            }
        }
        msj.innerHTML = textoAcierto;
    } else {
        msj.style.color = '#ef4444';
        let textoFallo = '✗ Fallaste. ';

        if (metaDesafio.esCorrecto) {
            textoFallo += `La operación era correcta. Recuerda: se multiplica en línea (${metaDesafio.n1}×${metaDesafio.n2} y ${metaDesafio.d1}×${metaDesafio.d2}).`;
        } else {
            textoFallo += 'Había un error grave. ';
            if (metaDesafio.motivoError === "multiplico_cruz") {
                textoFallo += `Fíjate, han multiplicado en cruz en lugar de en línea.`;
            } else if (metaDesafio.motivoError === "sumo_denominadores") {
                textoFallo += `Observa el denominador, lo han sumado en vez de multiplicarlo.`;
            } else {
                textoFallo += `Mira el denominador, ¡no lo han multiplicado!`;
            }
        }
        msj.innerHTML = textoFallo;
    }
  }

  // Bind events safely
  setTimeout(() => {
    document.getElementById('btn-iniciar-desafio').onclick = montarProblemaDesafio;
    document.getElementById('btn-correcto-desafio').onclick = function() { comprobarSolucionDesafio(true); };
    document.getElementById('btn-error-desafio').onclick = function() { comprobarSolucionDesafio(false); };
    montarProblemaDesafio();
  }, 100);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

