<div id="frac-div-cruz" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">La Máquina del Caramelo (División en Cruz)</h3>
<button id="btn-iniciar-div" class="btn-frac">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px;">
<p style="font-size: 1.15rem; font-weight: 600; color: #475569; margin-bottom: 30px;">Calcula la división multiplicando en cruz y escribe el resultado <span style="font-size: 0.95rem; font-weight: normal;">(sin simplificar)</span>:</p>
<div class="marco-actividad-div"><!-- Guías SVG en forma de aspa (Se muestran solo al fallar) --> <svg id="capa-guias-cruz" class="dibujo-guias-cruz" viewbox="0 0 500 200"> <defs> <marker id="flecha-naranja" markerwidth="6" markerheight="6" refx="5" refy="3" orient="auto"> <polygon points="0 0, 6 3, 0 6" fill="#f59e0b"></polygon> </marker> <marker id="flecha-morada" markerwidth="6" markerheight="6" refx="5" refy="3" orient="auto"> <polygon points="0 0, 6 3, 0 6" fill="#8b5cf6"></polygon> </marker> </defs> <!-- Aspa: N1 -> D2 -> ResN (Naranja) y D1 -> N2 -> ResD (Morado) --> <path d="M 80 60 L 210 140 Q 300 180 420 60" fill="none" stroke="#f59e0b" stroke-width="3" stroke-dasharray="6,4" marker-end="url(#flecha-naranja)"></path> <path d="M 80 140 L 210 60 Q 300 20 420 140" fill="none" stroke="#8b5cf6" stroke-width="3" stroke-dasharray="6,4" marker-end="url(#flecha-morada)"></path> </svg> <!-- Maquetación ESTATICA de Fracciones -->
<div class="caja-fraccion">
<div id="txt-div-n1" class="txt-num">6</div>
<div class="linea-frac"><br /></div>
<div id="txt-div-d1" class="txt-den">4</div>
</div>
<div class="simbolo-op">:</div>
<div class="caja-fraccion">
<div id="txt-div-n2" class="txt-num">3</div>
<div class="linea-frac"><br /></div>
<div id="txt-div-d2" class="txt-den">8</div>
</div>
<div class="simbolo-op" style="color: #64748b;">=</div>
<!-- Maquetación ESTATICA de Inputs -->
<div class="caja-fraccion"><input type="number" id="inp-div-n-res" class="inp-numero" placeholder="?" />
<div class="linea-frac" style="background: #0f172a;"><br /></div>
<input type="number" id="inp-div-d-res" class="inp-numero" placeholder="?" /></div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-revisar-div" class="btn-frac btn-comprobar">Comprobar División</button>
<div id="mensaje-estado-div" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 50px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  const ejBaseDiv = [
    {n1: 6, d1: 4, n2: 3, d2: 8},
    {n1: 8, d1: 6, n2: 4, d2: 9},
    {n1: 5, d1: 2, n2: 2, d2: 5},
    {n1: 4, d1: 2, n2: 2, d2: 7},
    {n1: 7, d1: 3, n2: 5, d2: 6},
    {n1: 9, d1: 3, n2: 2, d2: 4},
    {n1: 5, d1: 2, n2: 3, d2: 6},
    {n1: 8, d1: 7, n2: 5, d2: 3},
    {n1: 4, d1: 3, n2: 2, d2: 5},
    {n1: 9, d1: 2, n2: 2, d2: 4},
    {n1: 7, d1: 5, n2: 6, d2: 9},
    {n1: 10, d1: 8, n2: 6, d2: 11}
  ];

  let metaDiv = {};

  function gcdDiv(a, b) { return b === 0 ? a : gcdDiv(b, a % b); }

  function montarProblemaDiv() {
    let base = ejBaseDiv[Math.floor(Math.random() * ejBaseDiv.length)];

    metaDiv.n1 = base.n1; metaDiv.d1 = base.d1;
    metaDiv.n2 = base.n2; metaDiv.d2 = base.d2;

    if (Math.random() > 0.5) {
        let tN = metaDiv.n1; let tD = metaDiv.d1;
        metaDiv.n1 = metaDiv.n2; metaDiv.d1 = metaDiv.d2;
        metaDiv.n2 = tN; metaDiv.d2 = tD;
    }

    // En división, el resultado es el producto en cruz: N1*D2 / D1*N2
    metaDiv.resN = metaDiv.n1 * metaDiv.d2;
    metaDiv.resD = metaDiv.d1 * metaDiv.n2;

    // Actualizamos textos estáticos
    document.getElementById('txt-div-n1').innerText = metaDiv.n1;
    document.getElementById('txt-div-d1').innerText = metaDiv.d1;
    document.getElementById('txt-div-n2').innerText = metaDiv.n2;
    document.getElementById('txt-div-d2').innerText = metaDiv.d2;

    document.getElementById('txt-div-n1').style.color = '#0f172a';
    document.getElementById('txt-div-d1').style.color = '#0f172a';
    document.getElementById('txt-div-n2').style.color = '#0f172a';
    document.getElementById('txt-div-d2').style.color = '#0f172a';

    document.getElementById('capa-guias-cruz').style.display = 'none';

    let inN = document.getElementById('inp-div-n-res');
    let inD = document.getElementById('inp-div-d-res');

    inN.value = ''; inD.value = '';
    inN.disabled = false; inD.disabled = false;
    inN.style.background = '#f8fafc'; inN.style.borderColor = '#94a3b8'; inN.style.color = '#0284c7';
    inD.style.background = '#f8fafc'; inD.style.borderColor = '#94a3b8'; inD.style.color = '#0284c7';

    let btn = document.getElementById('btn-revisar-div');
    btn.disabled = false;
    btn.style.opacity = '1';

    document.getElementById('mensaje-estado-div').innerHTML = '';
    inN.focus();
  }

  function comprobarSolucionDiv() {
    let inN = document.getElementById('inp-div-n-res');
    let inD = document.getElementById('inp-div-d-res');

    let vN = parseInt(inN.value);
    let vD = parseInt(inD.value);
    let msj = document.getElementById('mensaje-estado-div');

    if (isNaN(vN) || isNaN(vD)) { 
      msj.style.color = '#ef4444'; 
      msj.innerHTML = '✗ Faltan números por rellenar en el resultado.'; 
      return; 
    }

    let bN = (vN === metaDiv.resN);
    let bD = (vD === metaDiv.resD);

    let divisor = gcdDiv(metaDiv.resN, metaDiv.resD);
    let simplificaOk = (vN === (metaDiv.resN / divisor)) && (vD === (metaDiv.resD / divisor));

    if ((bN && bD) || simplificaOk) {
      msj.style.color = '#10b981';
      msj.innerHTML = `✓ ¡Correcto! La división de fracciones se realiza multiplicando en cruz ("el caramelo").`;

      inN.disabled = true; inD.disabled = true;
      inN.style.background = '#d1fae5'; inN.style.borderColor = '#10b981'; inN.style.color = '#065f46';
      inD.style.background = '#d1fae5'; inD.style.borderColor = '#10b981'; inD.style.color = '#065f46';

      document.getElementById('capa-guias-cruz').style.display = 'none';
      document.getElementById('txt-div-n1').style.color = '#0f172a';
      document.getElementById('txt-div-n2').style.color = '#0f172a';
      document.getElementById('txt-div-d1').style.color = '#0f172a';
      document.getElementById('txt-div-d2').style.color = '#0f172a';

      document.getElementById('btn-revisar-div').disabled = true;
      document.getElementById('btn-revisar-div').style.opacity = '0.5';
    } else {
      msj.style.color = '#ef4444';
      let error = '✗ Incorrecto.<br><span style="font-size:1rem; font-weight:600;">';

      document.getElementById('capa-guias-cruz').style.display = 'block';

      if (!bN) {
        error += `Numerador: Multiplica en cruz hacia arriba (${metaDiv.n1} × ${metaDiv.d2}).<br>`;
        document.getElementById('txt-div-n1').style.color = '#f59e0b';
        document.getElementById('txt-div-d2').style.color = '#f59e0b';
      } else {
        document.getElementById('txt-div-n1').style.color = '#10b981';
        document.getElementById('txt-div-d2').style.color = '#10b981';
      }

      if (!bD) {
        error += `Denominador: Multiplica en cruz hacia abajo (${metaDiv.d1} × ${metaDiv.n2}).`;
        document.getElementById('txt-div-d1').style.color = '#8b5cf6';
        document.getElementById('txt-div-n2').style.color = '#8b5cf6';
      } else {
        document.getElementById('txt-div-d1').style.color = '#10b981';
        document.getElementById('txt-div-n2').style.color = '#10b981';
      }

      error += '</span>';
      msj.innerHTML = error;
    }
  }

  // Bind events safely
  setTimeout(() => {
    document.getElementById('btn-iniciar-div').onclick = montarProblemaDiv;
    document.getElementById('btn-revisar-div').onclick = comprobarSolucionDiv;
    document.getElementById('inp-div-d-res').addEventListener('keypress', e => { 
      if (e.key === 'Enter') comprobarSolucionDiv(); 
    });
    montarProblemaDiv();
  }, 100);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

