<div id="frac-lab-inverso" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b;"><!-- Cabecera -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; border-bottom: 2px solid #e2e8f0; padding-bottom: 15px; margin-bottom: 20px;">
<h3 style="margin: 0; color: #0f172a; font-size: 1.4rem; font-weight: 800;">El Laboratorio del Inverso</h3>
<button id="btn-nuevo-inv" class="btn-frac">Nuevo Ejercicio</button></div>
<!-- Zona de la Actividad -->
<div style="text-align: center; margin-bottom: 20px; max-width: 700px; margin: 0 auto;"><!-- Enunciado Principal -->
<div style="display: flex; justify-content: center; align-items: center; gap: 10px; margin-bottom: 25px; background: #ffffff; padding: 25px; border-radius: 12px; border: 2px dashed #94a3b8;">
<div class="caja-fraccion">
<div id="orig-n1" class="txt-num">6</div>
<div class="linea-frac"><br /></div>
<div id="orig-d1" class="txt-den">4</div>
</div>
<div class="simbolo-op">:</div>
<div class="caja-fraccion">
<div id="orig-n2" class="txt-num">3</div>
<div class="linea-frac"><br /></div>
<div id="orig-d2" class="txt-den">8</div>
</div>
</div>
<!-- PASO 1: Invertir y multiplicar -->
<div class="panel-paso" id="panel-p1-inv">
<div class="titulo-paso">Paso 1: Convierte la división en multiplicación (Invertir segunda fracción)</div>
<p style="font-size: 0.95rem; color: #475569; margin-top: 0; margin-bottom: 15px;">Deja la primera fracción igual, cambia los dos puntos por un signo de multiplicar y escribe la inversa de la segunda:</p>
<div style="display: flex; justify-content: center; align-items: center; flex-wrap: wrap; gap: 10px;">
<div class="caja-fraccion">
<div id="inv-f1-n" class="txt-num"></div>
<div class="linea-frac"><br /></div>
<div id="inv-f1-d" class="txt-den"></div>
</div>
<div class="simbolo-op">×</div>
<div class="caja-fraccion"><input type="number" id="inp-inv-n2" class="inp-numero" placeholder="?" />
<div class="linea-frac"><br /></div>
<input type="number" id="inp-inv-d2" class="inp-numero" placeholder="?" /></div>
</div>
</div>
<!-- PASO 2: Resultado Final -->
<div class="panel-paso" id="panel-p2-inv" style="opacity: 0.3; pointer-events: none; border-color: #10b981; background: #f0fdf4;">
<div class="titulo-paso" style="color: #065f46; border-color: #a7f3d0;">Paso 2: Multiplica en línea</div>
<div style="display: flex; justify-content: center; align-items: center; gap: 10px;">
<div class="caja-fraccion">
<div id="res-paso2-txt" style="font-size: 1.1rem; font-weight: bold; color: #065f46;"></div>
</div>
<span class="simbolo-op">=</span>
<div class="caja-fraccion"><input type="number" id="inp-res-n" class="inp-numero" placeholder="?" />
<div class="linea-frac" style="background: #059669;"><br /></div>
<input type="number" id="inp-res-d" class="inp-numero" placeholder="?" /></div>
</div>
</div>
</div>
<!-- Zona de Comprobación -->
<div style="text-align: center; margin-top: 30px; padding-top: 20px; border-top: 2px solid #e2e8f0;"><button id="btn-comprobar-inv" class="btn-frac btn-comprobar">Comprobar Inversión</button>
<div id="mensaje-estado-inv" style="margin-top: 15px; font-weight: bold; font-size: 1.15rem; min-height: 50px; line-height: 1.4;"></div>
</div>
</div>
<p>
<script>
(function() {
  let metaInv = {};
  let faseInv = 1;

  function gcdInv(a, b) { return b === 0 ? a : gcdInv(b, a % b); }

  function montarProblemaInv() {
    faseInv = 1;
    const pares = [
      {n1: 6, d1: 4, n2: 3, d2: 8},
      {n1: 8, d1: 6, n2: 4, d2: 9},
      {n1: 5, d1: 2, n2: 2, d2: 5},
      {n1: 7, d1: 3, n2: 5, d2: 6},
      {n1: 9, d1: 3, n2: 2, d2: 4},
      {n1: 5, d1: 2, n2: 3, d2: 6}
    ];

    let base = pares[Math.floor(Math.random() * pares.length)];
    metaInv.n1 = base.n1; metaInv.d1 = base.d1;
    metaInv.n2 = base.n2; metaInv.d2 = base.d2;

    // Resultado de la división original (en cruz)
    metaInv.targetResN = metaInv.n1 * metaInv.d2;
    metaInv.targetResD = metaInv.d1 * metaInv.n2;

    // Pintar valores originales
    document.getElementById('orig-n1').textContent = metaInv.n1;
    document.getElementById('orig-d1').textContent = metaInv.d1;
    document.getElementById('orig-n2').textContent = metaInv.n2;
    document.getElementById('orig-d2').textContent = metaInv.d2;

    // Paso 1 visual
    document.getElementById('inv-f1-n').textContent = metaInv.n1;
    document.getElementById('inv-f1-d').textContent = metaInv.d1;

    // Resetear paneles e inputs
    document.getElementById('panel-p1-inv').style.opacity = '1';
    document.getElementById('panel-p1-inv').style.pointerEvents = 'auto';
    document.getElementById('panel-p2-inv').style.opacity = '0.3';
    document.getElementById('panel-p2-inv').style.pointerEvents = 'none';

    ['inp-inv-n2', 'inp-inv-d2', 'inp-res-n', 'inp-res-d'].forEach(id => {
      let el = document.getElementById(id);
      el.value = ''; el.disabled = false;
      el.style.background = '#f8fafc'; el.style.borderColor = '#94a3b8'; el.style.color = '#0284c7';
    });

    let btn = document.getElementById('btn-comprobar-inv');
    btn.textContent = "Comprobar Inversión";
    btn.disabled = false; btn.style.opacity = '1';
    document.getElementById('mensaje-estado-inv').innerHTML = '';

    document.getElementById('inp-inv-n2').focus();
  }

  function comprobarPaso1Inv() {
    let inN = document.getElementById('inp-inv-n2');
    let inD = document.getElementById('inp-inv-d2');
    let vN = parseInt(inN.value);
    let vD = parseInt(inD.value);
    let msj = document.getElementById('mensaje-estado-inv');

    if (isNaN(vN) || isNaN(vD)) { msj.style.color = '#ef4444'; msj.innerHTML = '✗ Rellena la fracción inversa.'; return; }

    // La inversa de n2/d2 es d2/n2
    if (vN === metaInv.d2 && vD === metaInv.n2) {
      faseInv = 2;
      msj.style.color = '#10b981';
      msj.innerHTML = `✓ ¡Correcto! Has invertido la segunda fracción. Ahora multiplica en línea.`;

      inN.disabled = true; inD.disabled = true;
      inN.style.background = '#d1fae5'; inN.style.borderColor = '#10b981'; inN.style.color = '#065f46';
      inD.style.background = '#d1fae5'; inD.style.borderColor = '#10b981'; inD.style.color = '#065f46';

      document.getElementById('panel-p2-inv').style.opacity = '1';
      document.getElementById('panel-p2-inv').style.pointerEvents = 'auto';
      document.getElementById('res-paso2-txt').textContent = `${metaInv.n1} × ${metaInv.d2}  /  ${metaInv.d1} × ${metaInv.n2}`;

      let btn = document.getElementById('btn-comprobar-inv');
      btn.textContent = "Comprobar Multiplicación";
      document.getElementById('inp-res-n').focus();
    } else {
      msj.style.color = '#ef4444';
      msj.innerHTML = `✗ Inversa incorrecta. Recuerda darle la vuelta a la segunda fracción (${metaInv.n2}/${metaInv.d2} pasa a ser su recíproca).`;
    }
  }

  function comprobarPaso2Inv() {
    let inN = document.getElementById('inp-res-n');
    let inD = document.getElementById('inp-res-d');
    let vN = parseInt(inN.value);
    let vD = parseInt(inD.value);
    let msj = document.getElementById('mensaje-estado-inv');

    if (isNaN(vN) || isNaN(vD)) { msj.style.color = '#ef4444'; msj.innerHTML = '✗ Faltan números en el resultado.'; return; }

    let bN = (vN === metaInv.targetResN);
    let bD = (vD === metaInv.targetResD);

    let divisor = gcdInv(metaInv.targetResN, metaInv.targetResD);
    let simplificaOk = (divisor > 1 && vN === (metaInv.targetResN / divisor) && vD === (metaInv.targetResD / divisor));

    if ((bN && bD) || simplificaOk) {
      msj.style.color = '#10b981';
      msj.innerHTML = `🏆 ¡Excelente! Has dominado el método de la inversa para resolver la división.`;

      inN.disabled = true; inD.disabled = true;
      inN.style.background = '#d1fae5'; inN.style.borderColor = '#10b981'; inN.style.color = '#065f46';
      inD.style.background = '#d1fae5'; inD.style.borderColor = '#10b981'; inD.style.color = '#065f46';

      let btn = document.getElementById('btn-comprobar-inv');
      btn.disabled = true; btn.style.opacity = '0.5';
    } else {
      msj.style.color = '#ef4444';
      msj.innerHTML = `✗ Error al multiplicar en línea (${metaInv.n1}×${metaInv.d2} y ${metaInv.d1}×${metaInv.n2}). Revisa tus operaciones.`;
    }
  }

  setTimeout(() => {
    document.getElementById('btn-nuevo-inv').onclick = montarProblemaInv;
    document.getElementById('btn-comprobar-inv').onclick = () => { faseInv === 1 ? comprobarPaso1Inv() : comprobarPaso2Inv(); };
    document.getElementById('inp-inv-d2').addEventListener('keypress', e => { if (e.key === 'Enter' && faseInv === 1) comprobarPaso1Inv(); });
    document.getElementById('inp-res-d').addEventListener('keypress', e => { if (e.key === 'Enter' && faseInv === 2) comprobarPaso2Inv(); });
    montarProblemaInv();
  }, 100);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

